export function getBonsaiStyleDef(style?: string): BonsaiStyleDefinition {
  if (!style) return BONSAI_STYLES['MOYOGI'];
  const upper = style.toUpperCase().replace('-', '_');
  return BONSAI_STYLES[upper] || BONSAI_STYLES['MOYOGI'];
}

