  level: number;
  progressSeconds: number;
  gridX: number;
  gridY: number;
  x: number;
  y: number;
  col?: number;
  row?: number;
  field?: 'main' | 'left' | 'right';
  width?: number;
  height?: number;
  radius: number;
  color: string;
  flowerColor: string;
  potColor: string;
  potStyle: string;
  automatonTier: AutomatonTier; // 0 = none, 1, 2, 3
  pruneBoostTimer: number; // seconds remaining of 2.5x speed
