export function getInventoryStructureKey(type: DeployedStructureType): string {
  if (type === 't1_compost_feeder') return 't1_compost_feeder_inv';
  if (type === 't2_compost_feeder') return 't2_compost_feeder_inv';
  if (type === 't3_compost_feeder') return 't3_compost_feeder_inv';
  if (type === 't1_fertilizer_dripper') return 't1_fertilizer_dripper_inv';
  if (type === 't2_fertilizer_dripper') return 't2_fertilizer_dripper_inv';
  if (type === 't3_fertilizer_dripper') return 't3_fertilizer_dripper_inv';
  if (type === 'auto_unloader') return 'auto_unloader_inv';
  if (type === 'solar_panel') return 'solar_panels_inv';
  if (type === 'solar_farm_2x2') return 'solar_farm_2x2_inv';
  if (type === 'solar_farm_3x3') return 'solar_farm_3x3_inv';
  if (type === 'wind_turbine') return 'wind_turbines_inv';
  if (type === 'wind_farm_2x2') return 'wind_farm_2x2_inv';
  if (type === 'wind_farm_3x3') return 'wind_farm_3x3_inv';
  if (type === 'torii_gate') return 'torii_gate_inv';
  if (type === 'seven_lucky_gods') return 'seven_lucky_gods_inv';
  if (type === 'stone_lantern') return 'stone_lantern_inv';
  if (type === 'automaton_t1') return 'automaton_t1_inv';
  if (type === 'automaton_t2') return 'automaton_t2_inv';
  if (type === 'automaton_t3') return 'automaton_t3_inv';
  if (type === 'fertilizer_station' || type === 'chemical_station') return 'fertilizer_station_inv';
  if (type === 'empty_crystal_pedestal' || type === 'crystal_pedestal') return 'empty_crystal_pedestal_inv';
  if (type === 'water_feature' || type === 'decor_woven_wall') return 'water_feature_inv';
  if (type === 'bamboo_fence') return 'bamboo_fence_inv';
  if (type === 'zen_rock_formation' || type === 'decor_rock_formation') return 'zen_rock_formation_inv';
  if (type === 'growing_bamboo_formation' || type === 'decor_shrubbery_bush') return 'growing_bamboo_formation_inv';
  if (type === 'asparagus_fern_ball') return 'asparagus_fern_ball_inv';
  return `${type}_inv`;
}

export function getStructureInventoryCount(inv: SanctuaryInventory, type: DeployedStructureType): number {
  if (type === 't1_compost_feeder') {
    return inv.t1_compost_feeder_inv ?? inv.t1_compost_feeder ?? inv.deployables?.['t1_compost_feeder'] ?? inv.infrastructure?.['t1_compost_feeder'] ?? 0;
  }
  if (type === 't2_compost_feeder') {
    return inv.t2_compost_feeder_inv ?? inv.t2_compost_feeder ?? inv.deployables?.['t2_compost_feeder'] ?? inv.infrastructure?.['t2_compost_feeder'] ?? 0;
  }
  if (type === 't3_compost_feeder') {
    return inv.t3_compost_feeder_inv ?? inv.t3_compost_feeder ?? inv.deployables?.['t3_compost_feeder'] ?? inv.infrastructure?.['t3_compost_feeder'] ?? 0;
  }
  if (type === 't1_fertilizer_dripper') {
    return inv.t1_fertilizer_dripper_inv ?? inv.t1_fertilizer_dripper ?? inv.deployables?.['t1_fertilizer_dripper'] ?? inv.infrastructure?.['t1_fertilizer_dripper'] ?? 0;
  }
  if (type === 't2_fertilizer_dripper') {
    return inv.t2_fertilizer_dripper_inv ?? inv.t2_fertilizer_dripper ?? inv.deployables?.['t2_fertilizer_dripper'] ?? inv.infrastructure?.['t2_fertilizer_dripper'] ?? 0;
  }
  if (type === 't3_fertilizer_dripper') {
    return inv.t3_fertilizer_dripper_inv ?? inv.t3_fertilizer_dripper ?? inv.deployables?.['t3_fertilizer_dripper'] ?? inv.infrastructure?.['t3_fertilizer_dripper'] ?? 0;
  }
  if (type === 'auto_unloader') {
    return inv.auto_unloader_inv ?? inv.autoUnloader ?? inv.auto_unloaders_inv ?? 0;
  }
  if (type === 'solar_panel') {
    return inv.solar_panels_inv ?? inv.solar_panel_inv ?? inv.solarPanels ?? 0;
  }
  if (type === 'solar_farm_2x2') {
    return inv.solar_farm_2x2_inv ?? inv.infrastructure?.['solar_farm_2x2'] ?? inv.deployables?.['solar_farm_2x2'] ?? 0;
  }
  if (type === 'solar_farm_3x3') {
    return inv.solar_farm_3x3_inv ?? inv.infrastructure?.['solar_farm_3x3'] ?? inv.deployables?.['solar_farm_3x3'] ?? 0;
  }
  if (type === 'wind_turbine') {
    return inv.wind_turbines_inv ?? inv.wind_turbine_inv ?? inv.windTurbines ?? 0;
  }
  if (type === 'wind_farm_2x2') {
    return inv.wind_farm_2x2_inv ?? inv.infrastructure?.['wind_farm_2x2'] ?? inv.deployables?.['wind_farm_2x2'] ?? 0;
  }
  if (type === 'wind_farm_3x3') {
    return inv.wind_farm_3x3_inv ?? inv.infrastructure?.['wind_farm_3x3'] ?? inv.deployables?.['wind_farm_3x3'] ?? 0;
  }
  if (type === 'tool_compost_heap') {
    return inv.tool_compost_heap_inv ?? inv.tools?.compostHeap ?? 0;
  }
  if (type === 'tool_garden_well') {
    return inv.tool_garden_well_inv ?? inv.tools?.gardenWell ?? 0;
  }
  if (type === 'fertilizer_station' || type === 'chemical_station') {
    return inv.fertilizer_station_inv ?? inv.fertilizerStation ?? 0;
  }
  if (type === 'torii_gate') {
    return inv.torii_gate_inv ?? inv.decorations?.toriiGate ?? inv.decorations?.['torii_gate'] ?? 0;
  }
  if (type === 'seven_lucky_gods') {
    return (
      inv.seven_lucky_gods_inv ??
      inv.decorations?.['seven_lucky_gods'] ??
      inv.decorations?.sevenLuckyGods ??
      0
    );
  }
  if (type === 'stone_lantern') {
    return (
      inv.stone_lantern_inv ??
      inv.decorations?.['stone_lantern'] ??
      inv.decorations?.stoneLantern ??
      0
    );
  }
  if (type === 'automaton_t1') {
    return inv.automaton_t1_inv ?? inv.automatons_tier1 ?? 0;
  }
  if (type === 'automaton_t2') {
    return inv.automaton_t2_inv ?? inv.automatons_tier2 ?? 0;
  }
  if (type === 'automaton_t3') {
    return inv.automaton_t3_inv ?? inv.automatons_tier3 ?? 0;
  }
  if (type === 'irrigation_t1') {
    return inv.irrigation_t1_inv ?? 0;
  }
  if (type === 'irrigation_t2') {
    return inv.irrigation_t2_inv ?? 0;
  }
  if (type === 'irrigation_t3') {
    return inv.irrigation_t3_inv ?? 0;
  }
  if (type === 'empty_crystal_pedestal' || type === 'crystal_pedestal') {
    return inv.empty_crystal_pedestal_inv ?? 0;
  }
  if (type === 'water_feature' || type === 'decor_woven_wall') {
    return (
      inv.water_feature_inv ??
      inv.decor_woven_wall_inv ??
      inv.decorations?.['water_feature'] ??
      inv.decorations?.waterFeature ??
      inv.decorations?.wovenWall ??
      0
    );
  }
  if (type === 'bamboo_fence') {
    return (
      inv.bamboo_fence_inv ??
      inv.decorations?.['bamboo_fence'] ??
      inv.decorations?.bambooFence ??
      0
    );
  }
  if (type === 'zen_rock_formation' || type === 'decor_rock_formation') {
    return (
      inv.zen_rock_formation_inv ??
      inv.decor_rock_formation_inv ??
      inv.decorations?.['zen_rock_formation'] ??
      inv.decorations?.['zenRockFormation'] ??
      inv.decorations?.rockFormation ??
      0
    );
  }
  if (type === 'growing_bamboo_formation' || type === 'decor_shrubbery_bush') {
    return (
      inv.growing_bamboo_formation_inv ??
      inv.decor_shrubbery_bush_inv ??
      inv.decorations?.['growing_bamboo_formation'] ??
      inv.decorations?.['growingBamboo'] ??
      inv.decorations?.shrubbery ??
      0
    );
  }
  if (type === 'asparagus_fern_ball') {
    return (
      inv.asparagus_fern_ball_inv ??
      inv.decorations?.['asparagus_fern_ball'] ??
      inv.decorations?.['asparagusFernBall'] ??
      0
    );
  }
  const key = `${type}_inv`;
  return inv[key] ?? 0;
}

export function getWorkbenchName(tier: number): string {
  return tier === 3 ? 'Master Foundry' : tier === 2 ? 'Precision Workbench' : 'Artisan Workbench';
}

export function getWorkbenchAutomatonCapacity(tier: number): number {
  return tier === 1 ? 3 : tier === 2 ? 5 : 10;
}

