export function getFenceEdgeGeometry(
  col: number,
  row: number,
  side: 'top' | 'right' | 'bottom' | 'left' = 'top',
  field: 'main' | 'left' | 'right' = 'main',
): {
  edgeKey: string;
  side: 'top' | 'right' | 'bottom' | 'left';
  orientation: 'horizontal' | 'vertical';
  x: number;
  y: number;
} {
  const startX = field === 'left' ? SANCTUARY_LAYOUT.leftStartX : field === 'right' ? SANCTUARY_LAYOUT.rightStartX : SANCTUARY_LAYOUT.mainStartX;
  const startY = field === 'left' ? SANCTUARY_LAYOUT.leftStartY : field === 'right' ? SANCTUARY_LAYOUT.rightStartY : SANCTUARY_LAYOUT.mainStartY;
  const centerX = startX + col * SANCTUARY_LAYOUT.cellW;
  const centerY = startY + row * SANCTUARY_LAYOUT.cellH;

  switch (side) {
    case 'top':
      return {
        edgeKey: `${field}_H_${col}_${row}`,
        side: 'top',
        orientation: 'horizontal',
        x: centerX,
        y: centerY - SANCTUARY_LAYOUT.cellH / 2,
      };
    case 'bottom':
      return {
        edgeKey: `${field}_H_${col}_${row + 1}`,
        side: 'bottom',
        orientation: 'horizontal',
        x: centerX,
        y: centerY + SANCTUARY_LAYOUT.cellH / 2,
      };
    case 'left':
      return {
        edgeKey: `${field}_V_${col}_${row}`,
        side: 'left',
        orientation: 'vertical',
        x: centerX - SANCTUARY_LAYOUT.cellW / 2,
        y: centerY,
      };
    case 'right':
      return {
        edgeKey: `${field}_V_${col + 1}_${row}`,
        side: 'right',
        orientation: 'vertical',
        x: centerX + SANCTUARY_LAYOUT.cellW / 2,
        y: centerY,
      };
  }
}

/**
 * Compute Proximity Synergies for a planted bonsai:
 * Halo area depends strictly on Maturity Rating (Rating 1: 4 spots, Rating 2: 6 spots, Rating 3: 8 spots, Rating 4: 10 spots, Rating 5: 12 spots).
 * 🌿 "Growing Together": Each neighboring Bonsai in halo grants +10% Hydration Growth Speed (stackable)
 * 🌊 "Water Feature": Each neighboring Water Feature in halo grants +10% Hydration Growth Speed (stackable)
 * 🪨 "XP Boosted": Each neighboring Zen Rock Formation in halo grants +15% Level Up Experience (stackable)
 * 🎋 "Quick Prune": Each neighboring Growing Bamboo Formation in halo grants +0.25s Pruning Effect to manual care (stackable)
 * 🪴 "Efficient Pruning": Each neighboring Asparagus Fern Ball in halo grants +15% Chance for Extra Organic Waste on Level Up (stackable)
 * 🔮 "Cultivating Potential": Pedestals in halo provide +1 Cultivation Potential per level to their corresponding attribute
 * ⚠️ "Disrupted Zen": Neighboring industrial generator in halo or standing on disrupted soil inflicts -10% Growth Speed penalty.
 * ⛔ "Stalling Surroundings": 5 or more adjacent identical entities triggers Total Growth Stagnation (0% Growth Rate).
 * 🎋 "Bamboo Fence": Physically separates and blocks halo connections across borders!
 */
export function getBonsaiSynergies(
  bonsai: PlantedBonsai,
  plantedBonsais: PlantedBonsai[],
  structures: DeployedStructure[],
): BonsaiSynergies {
  const rating = getBonsaiMaturityRating(bonsai);
  const p = getPlotAtCoords(bonsai.x, bonsai.y) || { field: (bonsai as any).field || 'main', col: bonsai.col || 0, row: bonsai.row || 0 };
  const bField = p.field;
  const bCol = bonsai.col !== undefined ? bonsai.col : p.col;
  const bRow = bonsai.row !== undefined ? bonsai.row : p.row;
  const maxCols = bField === 'main' ? SANCTUARY_LAYOUT.mainCols : SANCTUARY_LAYOUT.sideCols;
  const maxRows = bField === 'main' ? SANCTUARY_LAYOUT.mainRows : SANCTUARY_LAYOUT.sideRows;
  const haloPlots = getBonsaiHaloPlots(bCol, bRow, rating, maxCols, maxRows);

  const isPlotInHalo = (c: number, r: number) => haloPlots.some((hp) => hp.col === c && hp.row === r);

  const fenceSet = new Set<string>();
  structures.forEach((s) => {
    if (s.type === 'bamboo_fence' && s.edgeKey) {
      fenceSet.add(s.edgeKey);
    }
  });

  const isBlocked = (c: number, r: number) => {
    if (bonsai.width === 2 && bonsai.height === 2) {
      let allBlocked = true;
      for (let dc = 0; dc <= 1; dc++) {
        for (let dr = 0; dr <= 1; dr++) {
          if (!isHaloBlockedByFence(bCol + dc, bRow + dr, c, r, fenceSet)) {
            allBlocked = false;
            break;
          }
        }
        if (!allBlocked) break;
      }
      return allBlocked;
    }
    return isHaloBlockedByFence(bCol, bRow, c, r, fenceSet);
  };

  let bonsaiCount = 0;
  plantedBonsais.forEach((other) => {
    if (other.id === bonsai.id) return;
    const op = getPlotAtCoords(other.x, other.y);
    if (!op || op.field !== bField) return;
    const oc = other.col !== undefined ? other.col : op.col;
    const or = other.row !== undefined ? other.row : op.row;
    const oW = other.width || 1;
    const oH = other.height || 1;
    let inHalo = false;
    for (let c = oc; c < oc + oW; c++) {
      for (let r = or; r < or + oH; r++) {
        if (isPlotInHalo(c, r) && !isBlocked(c, r)) {
          inHalo = true;
          break;
        }
      }
      if (inHalo) break;
    }
    if (inHalo) {
      bonsaiCount++;
    }
  });

  let wallCount = 0;
  let rockCount = 0;
  let bambooCount = 0;
  let fernBallCount = 0;
  let sevenLuckyGodsCount = 0;
  let stoneLanternCount = 0;
  let toriiCount = 0;
  let energyCount = 0;
  const crystalPedestals = {
    foliage: 0,
    branches: 0,
    trunk: 0,
    roots: 0,
    total: 0,
  };

  const countsByType: Record<string, number> = {};
  countsByType['bonsai'] = bonsaiCount;

  const disruptedPlots = getDisruptedZenPlots(structures);

  structures.forEach((s) => {
    if (s.type === 'bamboo_fence') {
      return;
    }

    const sp = getPlotAtCoords(s.x, s.y);
    if (!sp || sp.field !== bField) return;
    const sc = s.col !== undefined ? s.col : sp.col;
    const sr = s.row !== undefined ? s.row : sp.row;

    let inHalo = false;
    if (s.type === 'torii_gate') {
      if (s.orientation === 'vertical') {
        inHalo =
          (isPlotInHalo(sc, sr - 1) && !isBlocked(sc, sr - 1)) ||
          (isPlotInHalo(sc, sr) && !isBlocked(sc, sr)) ||
          (isPlotInHalo(sc, sr + 1) && !isBlocked(sc, sr + 1));
      } else {
        inHalo =
          (isPlotInHalo(sc - 1, sr) && !isBlocked(sc - 1, sr)) ||
          (isPlotInHalo(sc, sr) && !isBlocked(sc, sr)) ||
          (isPlotInHalo(sc + 1, sr) && !isBlocked(sc + 1, sr));
      }
    } else {
      inHalo = isPlotInHalo(sc, sr) && !isBlocked(sc, sr);
    }

    if (inHalo) {
      if (s.type === 'decor_pebble_path') {
        return;
      } else if (s.type === 'torii_gate') {
        toriiCount++;
      } else if (s.type === 'seven_lucky_gods') {
        sevenLuckyGodsCount++;
        countsByType['seven_lucky_gods'] = (countsByType['seven_lucky_gods'] || 0) + 1;
      } else if (s.type === 'stone_lantern') {
        stoneLanternCount++;
        countsByType['stone_lantern'] = (countsByType['stone_lantern'] || 0) + 1;
      } else if (s.type.startsWith('crystal_pedestal') || s.type === 'empty_crystal_pedestal') {
        countsByType['crystal_pedestal'] = (countsByType['crystal_pedestal'] || 0) + 1;
        if (s.socketedCrystal) {
          const str = s.socketedCrystal.strength || 0.5;
          crystalPedestals.total += str;
          if (s.socketedCrystal.crystalType === 'foliage') crystalPedestals.foliage += str;
          else if (s.socketedCrystal.crystalType === 'branches') crystalPedestals.branches += str;
          else if (s.socketedCrystal.crystalType === 'trunk') crystalPedestals.trunk += str;
          else if (s.socketedCrystal.crystalType === 'roots') crystalPedestals.roots += str;
        } else if (s.type === 'crystal_pedestal_foliage') {
          crystalPedestals.total += 1;
          crystalPedestals.foliage += 1;
        } else if (s.type === 'crystal_pedestal_branches') {
          crystalPedestals.total += 1;
          crystalPedestals.branches += 1;
        } else if (s.type === 'crystal_pedestal_trunk') {
          crystalPedestals.total += 1;
          crystalPedestals.trunk += 1;
        } else if (s.type === 'crystal_pedestal_roots') {
          crystalPedestals.total += 1;
          crystalPedestals.roots += 1;
        }
      } else {
        let typeKey = s.type as string;
        if (s.type === 'water_feature' || s.type === 'decor_woven_wall') typeKey = 'water_feature';
        else if (s.type === 'zen_rock_formation' || s.type === 'decor_rock_formation') typeKey = 'zen_rock_formation';
        else if (s.type === 'growing_bamboo_formation' || s.type === 'decor_shrubbery_bush') typeKey = 'growing_bamboo_formation';
        else if (s.type === 'asparagus_fern_ball') typeKey = 'asparagus_fern_ball';

        countsByType[typeKey] = (countsByType[typeKey] || 0) + 1;

        if (typeKey === 'water_feature') {
          wallCount++;
        } else if (typeKey === 'zen_rock_formation') {
          rockCount++;
        } else if (typeKey === 'growing_bamboo_formation') {
          bambooCount++;
        } else if (typeKey === 'asparagus_fern_ball') {
          fernBallCount++;
        } else if (
          s.type === 'solar_panel' ||
          s.type === 'wind_turbine' ||
          s.type === 'tool_compost_heap' ||
          s.type === 'fertilizer_station' ||
          s.type === 'auto_unloader'
        ) {
          energyCount++;
        }
      }
    }
  });

  // Check if bonsai itself is placed on a tile affected by Disrupted Zen
  let isOnDisruptedZenGround = false;
  for (let bc = bCol; bc < bCol + (bonsai.width || 1); bc++) {
    for (let br = bRow; br < bRow + (bonsai.height || 1); br++) {
      if (disruptedPlots.has(`${bField}_${br}_${bc}`) || disruptedPlots.has(`${bc},${br}`)) {
        isOnDisruptedZenGround = true;
        break;
      }
    }
    if (isOnDisruptedZenGround) break;
  }

  let degradedHaloTilesCount = 0;
  haloPlots.forEach((hp) => {
    if ((disruptedPlots.has(`${bField}_${hp.row}_${hp.col}`) || disruptedPlots.has(`${hp.col},${hp.row}`)) && !isBlocked(hp.col, hp.row)) {
      degradedHaloTilesCount++;
    }
  });

  const degradedTileCount = (isOnDisruptedZenGround ? 1 : 0) + degradedHaloTilesCount;
  const totalDisruptedZenPenalty = 10 * degradedTileCount;
  const isDisruptedZen = totalDisruptedZenPenalty > 0;

  let maxIdenticalCount = 0;
  let stalledEntityKey = '';
  for (const [k, count] of Object.entries(countsByType)) {
    if (count > maxIdenticalCount) {
      maxIdenticalCount = count;
      stalledEntityKey = k;
    }
  }

  const isStalled = maxIdenticalCount >= 5;

  let stalledEntityLabel = '';
  if (isStalled) {
    if (stalledEntityKey === 'bonsai') {
      stalledEntityLabel = 'Adjacent Bonsais';
    } else if (stalledEntityKey === 'water_feature') {
      stalledEntityLabel = 'Water Features';
    } else if (stalledEntityKey === 'zen_rock_formation') {
      stalledEntityLabel = 'Rock Formations';
    } else if (stalledEntityKey === 'growing_bamboo_formation') {
      stalledEntityLabel = 'Bamboo Formations';
    } else if (stalledEntityKey === 'asparagus_fern_ball') {
      stalledEntityLabel = 'Asparagus Fern Balls';
    } else if (stalledEntityKey === 'seven_lucky_gods') {
      stalledEntityLabel = 'Seven Lucky Gods Statues';
    } else if (stalledEntityKey === 'stone_lantern') {
      stalledEntityLabel = 'Stone Lanterns';
    } else if (stalledEntityKey === 'crystal_pedestal') {
      stalledEntityLabel = 'Crystal Pedestals';
    } else if (stalledEntityKey === 'tool_compost_heap') {
      stalledEntityLabel = 'Compost Heaps';
    } else if (stalledEntityKey === 'tool_garden_well') {
      stalledEntityLabel = 'Stone Wells';
    } else if (stalledEntityKey === 'solar_panel') {
      stalledEntityLabel = 'Solar Panels';
    } else if (stalledEntityKey === 'wind_turbine') {
      stalledEntityLabel = 'Wind Turbines';
    } else if (stalledEntityKey === 'auto_unloader') {
      stalledEntityLabel = 'Auto (Un-)Loaders';
    } else {
      stalledEntityLabel = 'Identical Entities';
    }
  }

  const hasToriiGate = toriiCount > 0;
  const haloMultiplier = hasToriiGate ? 2 : 1;

  const hasAdjacentBonsai = bonsaiCount > 0;
  const hasAdjacentWall = wallCount > 0;
  const hasAdjacentRock = rockCount > 0;
  const hasAdjacentBamboo = bambooCount > 0;
  const hasAdjacentFernBall = fernBallCount > 0;
  const hasAdjacentSevenLuckyGods = sevenLuckyGodsCount > 0;
  const hasAdjacentStoneLantern = stoneLanternCount > 0;
  const hasAdjacentBush = bambooCount > 0;
  const hasAdjacentEnergy = energyCount > 0;
  const hasAdjacentDecor =
    wallCount > 0 ||
    rockCount > 0 ||
    bambooCount > 0 ||
    fernBallCount > 0 ||
    sevenLuckyGodsCount > 0 ||
    stoneLanternCount > 0;

  const growingTogetherBonus = bonsaiCount * 0.10 * haloMultiplier;
  const privateGrowingBonus = wallCount * 0.10 * haloMultiplier;
  const baseGrowthRate = 1.0 + growingTogetherBonus + privateGrowingBonus;

  const disruptedPenaltyMultiplier = isDisruptedZen
    ? Math.max(0.05, 1 - totalDisruptedZenPenalty / 100)
    : 1.0;
  let rawGrowthMultiplier = Math.max(0.05, baseGrowthRate * disruptedPenaltyMultiplier);
  const growthMultiplier = isStalled ? 0 : rawGrowthMultiplier;
  const expMultiplier = 1.0 + (rockCount * 0.15) * haloMultiplier;
  const quickPruneBonus = (bambooCount * 0.25) * haloMultiplier;
  const extraWasteChance = (fernBallCount * 0.15) * haloMultiplier;
  const basePriceBonusRate = (sevenLuckyGodsCount * 0.01) * haloMultiplier;
  const zenPointChance = (stoneLanternCount * 0.005) * haloMultiplier;

  if (hasToriiGate) {
    crystalPedestals.foliage *= 2;
    crystalPedestals.branches *= 2;
    crystalPedestals.trunk *= 2;
    crystalPedestals.roots *= 2;
    crystalPedestals.total *= 2;
  }

  return {
    bonsaiCount,
    wallCount,
    rockCount,
    bambooCount,
    fernBallCount,
    sevenLuckyGodsCount,
    stoneLanternCount,
    hasToriiGate,
    haloMultiplier,
    basePriceBonusRate,
    zenPointChance,
    bushCount: bambooCount,
    decorCount: wallCount + rockCount + bambooCount + fernBallCount + sevenLuckyGodsCount + stoneLanternCount,
    pebbleCount: 0,
    energyCount,
    hasAdjacentBonsai,
    hasAdjacentWall,
    hasAdjacentRock,
    hasAdjacentBamboo,
    hasAdjacentFernBall,
    hasAdjacentSevenLuckyGods,
    hasAdjacentStoneLantern,
    hasAdjacentBush,
    hasAdjacentDecor,
    hasAdjacentPebbles: false,
    hasAdjacentEnergy,
    isDisruptedZen,
    totalDisruptedZenPenalty,
    degradedTileCount,
    disruptedPenaltyMultiplier,
    growthMultiplier,
    expMultiplier,
    quickPruneBonus,
    extraWasteChance,
    growingTogetherBonus,
    privateGrowingBonus,
    isStalled,
    stalledEntityLabel,
    stalledEntityKey,
    maxIdenticalCount,
    isOnDisruptedZenGround,
    crystalPedestals,
  };
}

