  const installedCraftingArmsRef = useRef<number>(0);
  const autoFabricatorLanesRef = useRef<AutoFabricatorLane[]>([]);

  // Permanent Sanctuary Storage (with Coins Currency, Purchased Maps, Expansions, Organic Waste & Composting)
