    playerXP: 0,
    scrap_metal: 25,
    copper_wire: 25,
    brass_gears: 25,
    circuit_boards: 25,
    electronic_chips: 25,
    organic_waste: 0,
    organic_compost: 0,
    condensed_organic_material: 0,
    condensedOrganicMaterial: 0,
    biochemicals: 0,
    fertilizer: 0,
    compost_s: 0,
    compost_m: 0,
    compost_l: 0,
    fertilizer_s: 0,
    fertilizer_m: 0,
