  // Pre-allocated Particle Pool (Smooth lightweight 50-particle budget, zero GC allocations)
  const MAX_PARTICLES = 50;
  const particlePoolRef = useRef<Particle[]>(
    Array.from({length: MAX_PARTICLES}, () => ({
      active: false,
      x: 0,
      y: 0,
      vx: 0,
      vy: 0,
      size: 2,
      color: '#ffffff',
      alpha: 0,
      life: 0,
      maxLife: 1,
    })),
  );

  const emitParticle = useCallback(
    (
      x: number,
      y: number,
      vx: number,
      vy: number,
      size: number,
      color: string,
      maxLife: number,
    ) => {
      const pool = particlePoolRef.current;
      for (let i = 0; i < pool.length; i++) {
        const p = pool[i];
        if (!p.active) {
          p.active = true;
          p.x = x;
          p.y = y;
          p.vx = vx;
          p.vy = vy;
          p.size = size;
          p.color = color;
          p.alpha = 1;
          p.life = 0;
          p.maxLife = maxLife;
          return;
        }
      }
      // If pool is full, recycle the oldest particle
      let oldestIdx = 0;
      let maxRatio = -1;
      for (let i = 0; i < pool.length; i++) {
        const ratio = pool[i].life / pool[i].maxLife;
        if (ratio > maxRatio) {
          maxRatio = ratio;
          oldestIdx = i;
        }
      }
      const p = pool[oldestIdx];
      p.active = true;
      p.x = x;
      p.y = y;
      p.vx = vx;
      p.vy = vy;
      p.size = size;
      p.color = color;
      p.alpha = 1;
      p.life = 0;
      p.maxLife = maxLife;
    },
    [],
  );

