  // HTML5 Gamepad Connection Detection and Lifecycle
  useEffect(() => {
    const handleGamepadConnected = (e: GamepadEvent) => {
      const name = e.gamepad?.id ? e.gamepad.id.replace(/\s*\([^)]*\)/g, '').trim() || 'Controller' : 'Controller';
      setConnectedGamepadName(name);
      triggerNotification(`🎮 Controller Connected: ${name}`, '#38bdf8', 4000);
      gameAudio.playConfirmSelect();
    };

    const handleGamepadDisconnected = () => {
      setConnectedGamepadName(null);
      triggerNotification('🎮 Controller Disconnected', '#f43f5e', 3500);
      gameAudio.playErrorBuzz();
    };

    // Check if controller is already connected on mount
    if (typeof navigator !== 'undefined' && navigator.getGamepads) {
      const gps = navigator.getGamepads();
      for (let i = 0; i < gps.length; i++) {
        const gp = gps[i];
        if (gp && gp.connected) {
          const name = gp.id ? gp.id.replace(/\s*\([^)]*\)/g, '').trim() || 'Controller' : 'Controller';
          setConnectedGamepadName(name);
          break;
        }
      }
    }

    window.addEventListener('gamepadconnected', handleGamepadConnected);
    window.addEventListener('gamepaddisconnected', handleGamepadDisconnected);
    return () => {
      window.removeEventListener('gamepadconnected', handleGamepadConnected);
      window.removeEventListener('gamepaddisconnected', handleGamepadDisconnected);
    };
  }, [triggerNotification]);

  const addFloatingText = useCallback((x: number, y: number, text: string, color = '#10b981') => {
    floatingTextsRef.current.push({
      id: `ft_${Date.now()}_${Math.random()}`,
      x,
      y,
      text,
      color,
      alpha: 1,
      life: 0,
      maxLife: 1.2,
    });
  }, []);

  // --- PROGRESSIVE PLAYER LEVEL & EXP SYSTEM ---
  const addPlayerXP = useCallback(
    (amount: number, sourceName?: string) => {
      const cleanXP = Math.max(0, Math.round(amount));
      if (cleanXP <= 0) return;
      const inv = sanctuaryInventoryRef.current;
      if (inv.player_level >= 100) {
        inv.player_level = 100;
        inv.player_exp = 0;
        refreshHud();
        return;
      }

      inv.player_exp = Math.round((inv.player_exp + cleanXP) * 100) / 100;

      let leveledUp = false;
      let levelsGained = 0;
      while (inv.player_level < 100) {
        const targetLevel = inv.player_level + 1;
        const needed = getXPRequirementForLevel(targetLevel);
        if (inv.player_exp >= needed) {
          inv.player_exp = Math.round((inv.player_exp - needed) * 100) / 100;
          inv.player_level += 1;
          inv.level = inv.player_level;
          inv.playerLevel = inv.player_level;
          const zenGained = 5; // +5 Zen Points per level up!
          inv.zen_essence += zenGained;
          leveledUp = true;
          levelsGained += 1;
        } else {
          break;
        }
      }

      if (inv.player_level >= 100) {
        inv.player_level = 100;
        inv.player_exp = 0;
      }

      if (leveledUp) {
        gameAudio.playLevelUpStinger();
        const totalZenGained = levelsGained * 5;
        triggerNotification(
          `🌟 LEVEL UP! Botanist Level ${inv.player_level}! (+${totalZenGained} Zen Point${totalZenGained > 1 ? 's' : ''} Awarded)`,
          '#ec4899',
        );
        if (locationRef.current === 'SANCTUARY') {
          addFloatingText(
            avatarRef.current.x,
            avatarRef.current.y - 45,
            `★ Level Up! Botanist Lv.${inv.player_level} (+${totalZenGained} Zen) ★`,
            '#facc15',
          );
        }
      } else if (sourceName) {
        addFloatingText(
          locationRef.current === 'SANCTUARY' ? avatarRef.current.x : 640,
          locationRef.current === 'SANCTUARY' ? avatarRef.current.y - 30 : 340,
          `+${cleanXP} XP`,
          '#38bdf8',
        );
      }

      refreshHud();
    },
    [addFloatingText, refreshHud, triggerNotification],
  );
  const gainPlayerExp = addPlayerXP;

  // Compute Maximum Battery Points (kWh) with Modules & Chassis Outfitting
  const getMaxRoverBattery = useCallback(() => {
    const base = (getConfig('roverBaseBattery') as number) || 500;
    const attached = sanctuaryInventoryRef.current.attached_rover_modules || [];
    const moduleBonus = attached.reduce((acc, modType) => {
      const cfg = ROVER_MODULE_CONFIGS[modType];
      return acc + (cfg?.category === 'battery' ? cfg.bonusValue : 0);
    }, 0);
    return base + moduleBonus;
  }, []);

  // Compute Maximum Cargo Weight with Modules & Chassis Outfitting
  const getMaxRoverCargo = useCallback(() => {
    const base = (getConfig('roverBaseCargo') as number) || 15.0;
    const attached = sanctuaryInventoryRef.current.attached_rover_modules || [];
    const moduleBonus = attached.reduce((acc, modType) => {
      const cfg = ROVER_MODULE_CONFIGS[modType];
      return acc + (cfg?.category === 'storage' ? cfg.bonusValue : 0);
    }, 0);
    return Math.round((base + moduleBonus) * 10) / 10;
  }, []);

  // Compute Maximum Dig Strikes Allowed (Base 2 + Careful Trowel skill ranks)
  const getMaxDigStrikes = useCallback(() => {
    return 2 + zenSkillsRef.current.carefulTrowel;
  }, []);

  // Check if a Sanctuary Grid coordinate (gx, gy) is unlocked based on expansion tier
  const isGridPlotUnlocked = useCallback((gx: number, gy: number) => {
    const tier = sanctuaryInventoryRef.current.sanctuary_expansion_tier || 0;
    const plot = getPlotAtCoords(gx, gy, tier);
    return plot ? plot.isUnlocked : false;
  }, []);

  // Helpers to check plot occupation accounting for 1x1, 2x2 bonsai footprints, and 3x1 torii gates
  const isPlotOccupiedByPlantedBonsai = useCallback(
    (c: number, r: number, field: 'main' | 'left' | 'right' = 'main', excludeBonsaiId?: string): boolean => {
      return plantedBonsaisRef.current.some((b) => {
        if (excludeBonsaiId && b.id === excludeBonsaiId) return false;
        const bField = (b as any).field || (b.x < SANCTUARY_LAYOUT.leftPathX ? 'left' : b.x > SANCTUARY_LAYOUT.rightPathX ? 'right' : 'main');
        if (bField !== field) return false;
        const bCol = b.col !== undefined ? b.col : 0;
        const bRow = b.row !== undefined ? b.row : 0;
        const bW = b.width || 1;
        const bH = b.height || 1;
        return c >= bCol && c < bCol + bW && r >= bRow && r < bRow + bH;
      });
    },
    [],
  );

  const isPlotOccupiedByStructure = useCallback(
    (c: number, r: number, field: 'main' | 'left' | 'right' = 'main', excludeStructId?: string): boolean => {
      return deployedStructuresRef.current.some((s) => {
        if (excludeStructId && s.id === excludeStructId) return false;
        if (s.type === 'bamboo_fence') return false; // Fences are boundary edge entities and do not occupy plot interiors
        const sField = (s as any).field || (s.x < SANCTUARY_LAYOUT.leftPathX ? 'left' : s.x > SANCTUARY_LAYOUT.rightPathX ? 'right' : 'main');
        if (sField !== field) return false;
        const sCol = s.col !== undefined ? s.col : 0;
        const sRow = s.row !== undefined ? s.row : 0;
        const sW = s.width || 1;
        const sH = s.height || 1;
        return c >= sCol && c < sCol + sW && r >= sRow && r < sRow + sH;
      });
    },
    [],
  );

  // Pre-render static terrain, promenade pebbles, lateral paths, and organic forest perimeter border to an offscreen canvas
  const renderOffscreenTerrain = useCallback(
    (targetWidth: number, targetHeight: number) => {
      let offCanvas = offscreenTerrainCanvasRef.current;
      if (!offCanvas) {
        offCanvas = document.createElement('canvas');
        offscreenTerrainCanvasRef.current = offCanvas;
      }
      if (offCanvas.width !== targetWidth || offCanvas.height !== targetHeight) {
        offCanvas.width = targetWidth;
        offCanvas.height = targetHeight;
      }
      const offCtx = offCanvas.getContext('2d');
      if (!offCtx) return;

      offCtx.clearRect(0, 0, targetWidth, targetHeight);

      // Warm greenhouse base ambiance
      const greenhouseGrad = offCtx.createLinearGradient(0, 0, 0, targetHeight);
      greenhouseGrad.addColorStop(0, 'rgba(15, 23, 42, 0.65)');
      greenhouseGrad.addColorStop(0.3, 'rgba(6, 78, 59, 0.45)');
      greenhouseGrad.addColorStop(0.8, 'rgba(6, 78, 59, 0.55)');
      greenhouseGrad.addColorStop(1, 'rgba(15, 23, 42, 0.75)');
      offCtx.fillStyle = greenhouseGrad;
      offCtx.fillRect(0, 50, targetWidth, targetHeight - 50);

      // Top Station Promenade Zen Pebble Walkway: extending cleanly from leftPathX to rightPathX
      offCtx.save();
      for (let px = SANCTUARY_LAYOUT.leftPathX; px <= SANCTUARY_LAYOUT.rightPathX; px += SANCTUARY_LAYOUT.cellW) {
        const variant = Math.floor((px - SANCTUARY_LAYOUT.leftPathX) / SANCTUARY_LAYOUT.cellW) % 5;
        renderPebbleCluster(offCtx, px, SANCTUARY_LAYOUT.topPathY, variant);
      }

      // Left Flanking Lateral Vertical Pebble Path: 8 discrete stepping stone clusters with grass gaps, exactly matching the top path stones
      for (let r = 0; r < SANCTUARY_LAYOUT.sideRows; r++) {
        const py = SANCTUARY_LAYOUT.leftStartY + r * SANCTUARY_LAYOUT.cellH;
        renderPebbleCluster(offCtx, SANCTUARY_LAYOUT.leftPathX, py, (r + 1) % 5);
      }

      // Right Flanking Lateral Vertical Pebble Path: 8 discrete stepping stone clusters with grass gaps, exactly matching the top path stones
      for (let r = 0; r < SANCTUARY_LAYOUT.sideRows; r++) {
        const py = SANCTUARY_LAYOUT.rightStartY + r * SANCTUARY_LAYOUT.cellH;
        renderPebbleCluster(offCtx, SANCTUARY_LAYOUT.rightPathX, py, (r + 3) % 5);
      }
      offCtx.restore();

      // Half-Circle Forest Perimeter Border:
      // Pushed significantly further outward so tree crowns and trunks do NOT overlap or clip into 8x8 fields or main field
      // Ensures left trees strictly stay to the left of (leftFieldX - 60px) and right trees to the right of (rightFieldX + 60px)
      offCtx.save();
      const { centerX, forestCenterY, forestRx, forestRy } = SANCTUARY_LAYOUT;
      const arcSteps = 64;

      const leftSafeBoundary = SANCTUARY_LAYOUT.leftStartX - (SANCTUARY_LAYOUT.cellW - 8) / 2 - 75; // well left of left field
      const rightSafeBoundary = SANCTUARY_LAYOUT.rightStartX + 7 * SANCTUARY_LAYOUT.cellW + (SANCTUARY_LAYOUT.cellW - 8) / 2 + 75; // well right of right field

      for (let i = 0; i <= arcSteps; i++) {
        const theta = Math.PI - (i / arcSteps) * Math.PI; // from PI (left) down to 0 (right)
        let edgeX = centerX + Math.cos(theta) * forestRx;
        const edgeY = forestCenterY + Math.sin(theta) * forestRy;

        // Ensure clearance alongside the 8x8 side fields
        if (edgeY <= SANCTUARY_LAYOUT.pathBottomY + 80) {
          if (theta >= Math.PI / 2) {
            edgeX = Math.min(edgeX, leftSafeBoundary);
          } else {
            edgeX = Math.max(edgeX, rightSafeBoundary);
          }
        }

        // Outer dense tree ring
        const outerX = theta >= Math.PI / 2 ? edgeX - 60 : edgeX + 60;
        const outerY = edgeY + 20;
        drawWildBarrierTree(offCtx, outerX - 32, outerY - 36, 64, i * 7, i * 11, i % 3 === 0);

        // Core tree perimeter line
        drawWildBarrierTree(offCtx, edgeX - 32, edgeY - 36, 64, i * 5, i * 13, i % 4 === 0);
      }

      // Flanking vertical forest borders above pathBottomY (from Y = 10 down alongside side fields)
      for (let py = 10; py <= SANCTUARY_LAYOUT.pathBottomY + 60; py += 48) {
        drawWildBarrierTree(offCtx, 40, py - 32, 64, 1, Math.floor(py), false);
        drawWildBarrierTree(offCtx, -15, py - 20, 64, 2, Math.floor(py), true);
        drawWildBarrierTree(offCtx, 2760, py - 32, 64, 3, Math.floor(py), false);
        drawWildBarrierTree(offCtx, 2815, py - 20, 64, 4, Math.floor(py), true);
      }
      offCtx.restore();

      offscreenTerrainDirtyRef.current = false;
    },
    [],
  );

    // Compute Current Total Rover Cargo Weight (kg)
  const getCargoWeight = useCallback(() => {
    const back = backpackInventoryRef.current;
    const crystalWeight = (back.crystals || []).reduce(
      (acc, c) => acc + (c.strength === 1.0 ? 1.0 : 0.5),
      0,
    );
    const w =
      back.scrap_metal * ITEM_WEIGHTS.scrap_metal +
      back.copper_wire * ITEM_WEIGHTS.copper_wire +
      back.brass_gears * ITEM_WEIGHTS.brass_gears +
      back.circuit_boards * ITEM_WEIGHTS.circuit_boards +
      back.electronic_chips * ITEM_WEIGHTS.electronic_chips +
      crystalWeight +
      back.saplings.length * ITEM_WEIGHTS.sapling;
    return Math.round(w * 10) / 10;
  }, []);

  // Compute Power Grid metrics (Dynamically sums DEPLOYED solar panels, wind turbines & farms with stackable Proximity Resonance)
  const getPowerMetrics = useCallback(() => {
    const deployedSolarList = deployedStructuresRef.current.filter(
      (s) => s.type === 'solar_panel' || s.type === 'solar_farm_2x2' || s.type === 'solar_farm_3x3',
    );
    const deployedTurbineList = deployedStructuresRef.current.filter(
      (s) => s.type === 'wind_turbine' || s.type === 'wind_farm_2x2' || s.type === 'wind_farm_3x3',
    );

    let solarKw = 0;
    let solarBonusCount = 0;
    deployedSolarList.forEach((panel) => {
      const {total, count} = getSolarStructureOutput(panel, deployedStructuresRef.current);
      solarKw += total;
      solarBonusCount += count;
    });

    let turbineKw = 0;
    let turbineBonusCount = 0;
    deployedTurbineList.forEach((turbine) => {
      const {total, count} = getWindStructureOutput(turbine, deployedStructuresRef.current);
      turbineKw += total;
      turbineBonusCount += count;
    });

    // Apply Solar Expert & Wind Expert skills (+10% power per level)
    const solarSkill = zenSkillsRef.current.solarExpert || 0;
    if (solarSkill > 0) {
      solarKw = Math.round(solarKw * (1 + solarSkill * 0.10) * 10) / 10;
    }
    const windSkill = zenSkillsRef.current.windExpert || 0;
    if (windSkill > 0) {
      turbineKw = Math.round(turbineKw * (1 + windSkill * 0.10) * 10) / 10;
    }

    const totalGenerated = solarKw + turbineKw;

    let totalRequired = 0;
    let activeAutomatonsCount = 0;

    plantedBonsaisRef.current.forEach((b) => {
      if (b.automatonTier > 0) {
        activeAutomatonsCount += 1;
        const tierConfig = getAutomatonConfig(b.automatonTier);
        totalRequired += tierConfig?.kwDrain || (b.automatonTier === 3 ? 12 : b.automatonTier === 2 ? 7 : 4);
      }
    });

    deployedStructuresRef.current.forEach((s) => {
      if (s.type === 'automaton_t1') {
        activeAutomatonsCount += 1;
        totalRequired += 4;
      } else if (s.type === 'automaton_t2') {
        activeAutomatonsCount += 1;
        totalRequired += 7;
      } else if (s.type === 'automaton_t3') {
        activeAutomatonsCount += 1;
        totalRequired += 12;
      } else if (s.type === 'auto_unloader') {
        totalRequired += 2;
      } else if (s.type === 't1_compost_feeder') {
        totalRequired += 6;
      } else if (s.type === 't2_compost_feeder') {
        totalRequired += 10;
      } else if (s.type === 't3_compost_feeder') {
        totalRequired += 16;
      } else if (s.type === 't1_fertilizer_dripper') {
        totalRequired += 7;
      } else if (s.type === 't2_fertilizer_dripper') {
        totalRequired += 12;
      } else if (s.type === 't3_fertilizer_dripper') {
        totalRequired += 18;
      }
    });

    // Installed Crafting Assembly Arms & Workbench Modules power drain
    let craftingPowerDrain = installedCraftingArmsRef.current * 3;
    const attachedWbModules = sanctuaryInventoryRef.current.attached_workbench_modules || [];
    attachedWbModules.forEach((m) => {
      if (m === 'assembly_module_t1') craftingPowerDrain += 2;
      else if (m === 'assembly_module_t2') craftingPowerDrain += 3;
      else if (m === 'assembly_module_t3') craftingPowerDrain += 4;
      else if (m === 'overclock_module_t1') craftingPowerDrain += 3;
      else if (m === 'overclock_module_t2') craftingPowerDrain += 5;
      else if (m === 'overclock_module_t3') craftingPowerDrain += 7;
      else craftingPowerDrain += 3;
    });
    totalRequired += craftingPowerDrain;

    // Installed Auto-Fabrication Lanes consume power by tier: T1 (6 kW), T2 (10 kW), T3 (14 kW)
    let autoFabricatorPowerDrain = 0;
    autoFabricatorLanesRef.current.forEach((lane) => {
      autoFabricatorPowerDrain += lane.tier === 1 ? 6 : lane.tier === 3 ? 14 : 10;
    });
    totalRequired += autoFabricatorPowerDrain;

    // Installed Rover Modules power drain:
    // T1 Storage: 4 kW, T2 Storage: 7 kW, T3 Storage: 10 kW
    // T1 Battery: 3 kW, T2 Battery: 5 kW, T3 Battery: 7 kW
    // T1 Radar: 5 kW, T2 Radar: 8 kW, T3 Radar: 12 kW
    let roverPowerDrain = 0;
    const attachedRover = sanctuaryInventoryRef.current.attached_rover_modules || [];
    attachedRover.forEach((rm) => {
      const cfg = ROVER_MODULE_CONFIGS[rm];
      if (cfg && typeof cfg.kw === 'number') {
        roverPowerDrain += cfg.kw;
      } else {
        if (rm === 'storage_1') roverPowerDrain += 4;
        else if (rm === 'storage_2') roverPowerDrain += 7;
        else if (rm === 'storage_3') roverPowerDrain += 10;
        else if (rm === 'battery_1') roverPowerDrain += 3;
        else if (rm === 'battery_2') roverPowerDrain += 5;
        else if (rm === 'battery_3') roverPowerDrain += 7;
        else if (rm === 'radar_1') roverPowerDrain += 5;
        else if (rm === 'radar_2') roverPowerDrain += 8;
        else if (rm === 'radar_3') roverPowerDrain += 12;
      }
    });
    totalRequired += roverPowerDrain;

    const isPowerSufficient = totalGenerated >= totalRequired;

    return {
      deployedSolar: deployedSolarList.length,
      deployedTurbines: deployedTurbineList.length,
      solarKw,
      turbineKw,
      solarBonusCount,
      turbineBonusCount,
      totalGenerated,
      totalRequired,
      activeAutomatonsCount,
      craftingPowerDrain,
      autoFabricatorPowerDrain,
      roverPowerDrain,
      isPowerSufficient,
    };
  }, []);

  // Helper to snap coordinates to sanctuary grid (Main, Left, or Right)
  const snapToSanctuaryGrid = useCallback((x: number, y: number) => {
    const p = getPlotAtCoords(x, y, 99) || getPreviewPlot(x, y, 99);
    return {
      col: p.col,
      row: p.row,
      x: p.centerX,
      y: p.centerY,
      field: p.field,
    };
  }, []);

  // Helper to get distance zone name and properties based on biome & distance
  const getZoneInfo = useCallback((biomeId: ExpeditionBiomeId, distSteps: number) => {
    const biome = EXPEDITION_BIOMES[biomeId];
    if (distSteps <= 20) {
      return {
        name: `🌿 ${biome.name} - Close Range`,
        tier: 1,
        color: biome.accentColor,
        description: `Close range perimeter (0-20 steps). Drain: ${biome.batteryCostPerStep} kWh/step.`,
      };
    } else if (distSteps <= 40) {
      return {
        name: `🍂 ${biome.name} - Middle Range`,
        tier: 2,
        color: '#f59e0b',
        description: `Middle range perimeter (21-40 steps). Drain: ${biome.batteryCostPerStep} kWh/step.`,
      };
    } else if (distSteps <= 60) {
      return {
        name: `✨ ${biome.name} - Far Range`,
        tier: 3,
        color: '#38bdf8',
        description: `Far range perimeter (41-60 steps). Drain: ${biome.batteryCostPerStep} kWh/step.`,
      };
    } else if (distSteps <= 80) {
      return {
        name: `🏔️ ${biome.name} - Expansion I`,
        tier: 4,
        color: '#818cf8',
        description: `Expansion I sector (61-80 steps). Drain: ${biome.batteryCostPerStep} kWh/step.`,
      };
    } else if (distSteps <= 100) {
      return {
        name: `🌌 ${biome.name} - Expansion II`,
        tier: 5,
        color: '#a855f7',
        description: `Expansion II sector (81-100 steps). Drain: ${biome.batteryCostPerStep} kWh/step.`,
      };
    } else if (distSteps <= 120) {
      return {
        name: `🔮 ${biome.name} - Expansion III`,
        tier: 6,
        color: '#c084fc',
        description: `Expansion III sector (101-120 steps). Drain: ${biome.batteryCostPerStep} kWh/step.`,
      };
    } else if (distSteps <= 140) {
      return {
        name: `⚡ ${biome.name} - Expansion IV`,
        tier: 7,
        color: '#e879f9',
        description: `Expansion IV sector (121-140 steps). Drain: ${biome.batteryCostPerStep} kWh/step.`,
      };
    } else {
      return {
        name: `👑 ${biome.name} - Deep Frontier V`,
        tier: 8,
        color: '#f43f5e',
        description: `Deep Frontier sector (141-160 steps). Drain: ${biome.batteryCostPerStep} kWh/step.`,
      };
    }
  }, []);

  // Generate Wilderness Excursion Grid Map with unified combined probability calculation per tile
  const generateExcursionGridWorld = useCallback((biomeId: ExpeditionBiomeId) => {
    const nodes = new Map<string, ExcursionTileNode>();
    const radius = 160;
    const seed = worldSeedRef.current;

    // Pseudo-random hash generator based on world seed
    const pseudoNoise = (x: number, y: number, offset: number) => {
      const s = Math.sin(x * 12.9898 + y * 78.233 + offset + seed * 0.001) * 43758.5453;
      return s - Math.floor(s);
    };

    const dowsingBonus =
      biomeId === 'FOOTHILLS'
        ? ((zenSkillsRef.current.botanicalDowsingArea1 || zenSkillsRef.current.botanicalDowsing || 0) * 0.02)
        : biomeId === 'HIGHLANDS'
        ? ((zenSkillsRef.current.botanicalDowsingArea2 || 0) * 0.02)
        : ((zenSkillsRef.current.botanicalDowsingArea3 || 0) * 0.02);

    const prospectingBonus =
      biomeId === 'FOOTHILLS'
        ? ((zenSkillsRef.current.resourceProspectingArea1 || zenSkillsRef.current.resourceProspecting || 0) * 0.02)
        : biomeId === 'HIGHLANDS'
        ? ((zenSkillsRef.current.resourceProspectingArea2 || 0) * 0.02)
        : ((zenSkillsRef.current.resourceProspectingArea3 || 0) * 0.02);

    const artifactHunterBonus =
      biomeId === 'FOOTHILLS'
        ? ((zenSkillsRef.current.artifactHunterArea1 || 0) * 0.0005)
        : biomeId === 'HIGHLANDS'
        ? ((zenSkillsRef.current.artifactHunterArea2 || 0) * 0.0005)
        : ((zenSkillsRef.current.artifactHunterArea3 || 0) * 0.0005);

    for (let gx = -radius; gx <= radius; gx++) {
      for (let gy = -radius; gy <= radius; gy++) {
        if (gx === 0 && gy === 0) continue;
        if (Math.abs(gx) <= 1 && Math.abs(gy) <= 1) continue;

        const dist = Math.hypot(gx, gy);
        if (dist > 160) continue; // Boundary expands up to 160 steps

        const isClose = dist <= 20;
        const isMid = dist > 20 && dist <= 40;

        const bonsaiRate = 0.08 + dowsingBonus;
        const baseResRate = isClose ? 0.04 : isMid ? 0.06 : 0.08;
        const resourceRate = baseResRate + prospectingBonus;
        const baseCrystalRate = getCrystalArtifactBaseRate(biomeId, dist);
        const crystalRate = baseCrystalRate + artifactHunterBonus;

        const tileRoll = pseudoNoise(gx, gy, 111.1);

        if (tileRoll < bonsaiRate) {
          // 1. BONSAI SEEDLING TILE
          let chosenLeafType: BonsaiLeafType = 'circle';
          const speciesRoll = pseudoNoise(gx, gy, 777.7);
          const distTable = AREA_SPECIES_DISTRIBUTION[biomeId] || AREA_SPECIES_DISTRIBUTION['FOOTHILLS'];
          let accSpeciesW = 0;
          for (const [sKey, sWeight] of Object.entries(distTable)) {
            accSpeciesW += sWeight;
            if (speciesRoll <= accSpeciesW) {
              chosenLeafType = sKey as BonsaiLeafType;
              break;
            }
          }

          const chosenLeaf = LEAF_TYPE_CONFIGS[chosenLeafType];
          const weights = getMaturityWeights(biomeId, dist);
          const wArray = [weights.sprout, weights.sapling, weights.notable, weights.refined, weights.premium];
          const totalW = wArray.reduce((a, b) => a + b, 0);
          const matRoll = pseudoNoise(gx, gy, 555.5) * totalW;

          let chosenMaturity: MaturityTier = 'sprout';
          let chosenMaturityIdx = 0;
          const maturityList: MaturityTier[] = ['sprout', 'sapling', 'notable', 'refined', 'premium'];
          let accW = 0;
          for (let i = 0; i < wArray.length; i++) {
            accW += wArray[i];
            if (matRoll <= accW) {
              chosenMaturity = maturityList[i];
              chosenMaturityIdx = i;
              break;
            }
          }

          const spawnChance = totalW > 0 ? (wArray[chosenMaturityIdx] / totalW) : 1.0;

          nodes.set(`${gx},${gy}`, {
            id: `sap_${gx}_${gy}`,
            tileX: gx,
            tileY: gy,
            type: 'SAPLING',
            saplingLeafType: chosenLeaf.id,
            saplingGroup: chosenLeaf.group,
            saplingMaturity: chosenMaturity,
            saplingSpecies: chosenLeaf.id,
            saplingName: `${getSpeciesName(chosenLeaf.id)} Bonsai`,
            saplingRarity: chosenLeaf.rarity,
            spawnChance,
            collected: false,
          });
        } else if (tileRoll < bonsaiRate + resourceRate) {
          // 2. RESOURCE DEPOSIT TILE
          const resRoll = pseudoNoise(gx, gy, 888.8);
          const resYield = pickResourceDepositEx(biomeId, dist, resRoll);
          let resType = resYield.key;
          if (resYield.amount === 2 && resType === 'scrap_metal') {
            resType = 'scrap_metal_double';
          } else if (resYield.amount === 3 && resType === 'scrap_metal') {
            resType = 'scrap_metal_triple';
          } else if (resYield.amount === 2 && resType === 'copper_wire') {
            resType = 'copper_wire_double';
          } else if (resYield.amount === 3 && resType === 'copper_wire') {
            resType = 'copper_wire_triple';
          } else if (resYield.amount === 2 && resType === 'brass_gears') {
            resType = 'brass_gears_double';
          } else if (resYield.amount === 2 && resType === 'circuit_boards') {
            resType = 'circuit_boards_double';
          }

          nodes.set(`${gx},${gy}`, {
            id: `res_${gx}_${gy}`,
            tileX: gx,
            tileY: gy,
            type: 'RESOURCE',
            resourceType: resType,
            resourceYield: resYield.amount,
            collected: false,
          });
        } else if (tileRoll < bonsaiRate + resourceRate + crystalRate) {
          // 3. CRYSTAL SHARD TILE (25% chance for each: Foliage, Branches, Trunk, Roots)
          const cTypeRoll = pseudoNoise(gx, gy, 333.3);
          let crystalType: CrystalAttributeType = 'foliage';
          if (cTypeRoll < 0.25) crystalType = 'foliage';
          else if (cTypeRoll < 0.50) crystalType = 'branches';
          else if (cTypeRoll < 0.75) crystalType = 'trunk';
          else crystalType = 'roots';

          let strength: 0.5 | 1.0 = 0.5;
          if (biomeId === 'OVERGROWTH') {
            const strRoll = pseudoNoise(gx, gy, 444.4);
            if (strRoll < 0.10) {
              strength = 1.0;
            }
          }

          const cTypeLabel =
            crystalType === 'foliage'
              ? 'Foliage'
              : crystalType === 'branches'
              ? 'Branch'
              : crystalType === 'trunk'
              ? 'Trunk'
              : 'Root';

          const crystalInfo = {
            foliage: { name: `✨ Foliage Crystal (${strength} Strength)`, color: '#22c55e' },
            branches: { name: `✨ Branch Crystal (${strength} Strength)`, color: '#eab308' },
            trunk: { name: `✨ Trunk Crystal (${strength} Strength)`, color: '#ef4444' },
            roots: { name: `✨ Root Crystal (${strength} Strength)`, color: '#3b82f6' },
          }[crystalType];

          nodes.set(`${gx},${gy}`, {
            id: `crys_${gx}_${gy}`,
            tileX: gx,
            tileY: gy,
            type: 'CRYSTAL',
            crystalType,
            crystalStrength: strength,
            crystalName: crystalInfo.name,
            crystalColor: crystalInfo.color,
            collected: false,
          });
        }
      }
    }

    excursionNodesRef.current = nodes;
  }, []);

  // Launch Expedition into a specific Biome
  const startBiomeExcursion = useCallback(
    (biomeId: ExpeditionBiomeId) => {
      const biome = EXPEDITION_BIOMES[biomeId];
      const inv = sanctuaryInventoryRef.current;
      const reqKey = biome.requiredMapKey;

      const isAreaUnlocked =
        biome.unlockedByDefault ||
        (reqKey && inv[reqKey]) ||
        (biomeId === 'HIGHLANDS' && (inv.has_map_highlands || inv['area2_base'] || inv.unlockedMaps?.includes('area2_base'))) ||
        (biomeId === 'OVERGROWTH' && (inv.has_map_overgrowth || inv['area3_base'] || inv.unlockedMaps?.includes('area3_base')));

      if (!isAreaUnlocked) {
        gameAudio.playErrorBuzz();
        triggerNotification(`Locked: Purchase map at Botanical Market (${biome.mapCost} Verdure)`, '#ef4444');
        return;
      }

      // 1. Store exact Sanctuary player position
      sanctuaryPlayerPosRef.current = {
        x: avatarRef.current.x,
        y: avatarRef.current.y,
      };

      setIsBiomeSelectOpen(false);
      setActiveBiomeId(biomeId);
      activeBiomeIdRef.current = biomeId;
      worldSeedRef.current = Date.now() + Math.floor(Math.random() * 100000);

      generateExcursionGridWorld(biomeId);

      // Reset Fog of War and reveal initial vision around Basecamp (0, 0)
      exploredTilesRef.current = new Set();
      revealFogAroundRover(0, 0);

      hasMovedOffSpawnRef.current = false;
      setHasMovedOffSpawn(false);

      const maxBat = getMaxRoverBattery();
      roverRef.current = {
        tileX: 0,
        tileY: 0,
        visualX: EXCURSION_TILE_SIZE / 2,
        visualY: EXCURSION_TILE_SIZE / 2,
        facing: 'up',
        facingDirection: 1,
        rotation: 0,
        batteryKwh: maxBat,
        maxBatteryKwh: maxBat,
        isMovingAnim: false,
        moveCooldown: 0,
        maxDistanceReached: 0,
        hasMovedOffSpawn: false,
        stepsTaken: 0,
      };

      cameraRef.current = {
        x: EXCURSION_TILE_SIZE / 2 - canvasWidth / 2,
        y: EXCURSION_TILE_SIZE / 2 - canvasHeight / 2,
      };

      backpackInventoryRef.current = {
        scrap_metal: 0,
        copper_wire: 0,
        brass_gears: 0,
        circuit_boards: 0,
        electronic_chips: 0,
        crystals: [],
        saplings: [],
      };

      setLocation('EXCURSION');
      gameAudio.playPowerupChime();
      triggerNotification(
        `🚙 Deployed to ${biome.name}! Drain: ${biome.batteryCostPerStep} kWh/step • Battery: ${maxBat} kWh`,
        biome.accentColor,
      );
    },
    [generateExcursionGridWorld, getMaxRoverBattery, triggerNotification],
  );

  // Finish Excursion and Build Report Modal
  const finishExcursion = useCallback(
    (isStranded: boolean) => {
      const back = backpackInventoryRef.current;
      const rover = roverRef.current;
      const currentBiome = EXPEDITION_BIOMES[activeBiomeIdRef.current];
      const retention = isStranded ? 0.35 : 1.0;

      const keys: ResourceItemKey[] = [
        'scrap_metal',
        'copper_wire',
        'brass_gears',
        'circuit_boards',
        'electronic_chips',
      ];

      const itemBreakdown = keys.map((k) => {
        const collected = back[k];
        let retained = Math.floor(collected * retention);
        if (collected > 0 && retained === 0 && Math.random() < 0.5) retained = 1;
        retained = Math.min(collected, retained);
        const lost = collected - retained;

        const nameMap: Record<ResourceItemKey, string> = {
          scrap_metal: '🔩 Scrap Metal',
          copper_wire: '⚡ Copper Wire',
          brass_gears: '⚙️ Brass Gears',
          circuit_boards: '🟩 Circuit Boards',
          electronic_chips: '💎 Electronic Chips',
          scrap_metal_double: '🔩 Heavy Scrap Metal (2x)',
          copper_wire_double: '⚡ Heavy Copper Wire (2x)',
          scrap_metal_triple: '🔩 Scrap Metal Trio (3x)',
          copper_wire_triple: '⚡ Copper Wire Spools (3x)',
          brass_gears_double: '⚙️ Interlocking Brass Gears (2x)',
          circuit_boards_double: '🟩 Layered Microcircuits (2x)',
        };

        return {
          key: k,
          name: nameMap[k],
          collected,
          retained,
          lost,
        };
      });

      const totalSaplings = back.saplings.length;
      const retainedSaplingCount = Math.floor(totalSaplings * retention);
      const saplingBreakdown = back.saplings.map((sap, idx) => ({
        name: getBonsaiDisplayName(sap),
        leafType: sap.leafType,
        group: sap.group,
        maturity: sap.maturity || 'sprout',
        rarity: sap.rarity,
        retained: idx < retainedSaplingCount || !isStranded,
      }));

      const backCrystals = back.crystals || [];
      const retainedCrystalsCount = Math.floor(backCrystals.length * retention);
      const crystalBreakdown = backCrystals.map((cry, idx) => ({
        item: cry,
        name: cry.name,
        retained: idx < retainedCrystalsCount || !isStranded,
      }));

      // Calculate total secured XP upon return based on surviving/retained items only
      let totalExpeditionXP = 0;

      // Resources: 3 XP per Scrap Metal, 6 XP per Copper Wire, 12 XP per Gear, 25 XP per Circuit, 50 XP per Chip
      itemBreakdown.forEach((item) => {
        if (item.retained > 0) {
          totalExpeditionXP += calculateFindingResourceXP(item.key, item.retained);
        }
      });

      // Crystals: 25 XP (0.5 pt), 50 XP (1.0 pt), 100 XP (1.5 pt)
      crystalBreakdown.forEach((c) => {
        if (c.retained) {
          totalExpeditionXP += calculateFindingCrystalXP(c.item.strength);
        }
      });

      // Seedlings/Bonsais: Math.round(5.0 * maturityFactor * speciesOdds)
      saplingBreakdown.forEach((s) => {
        if (s.retained) {
          totalExpeditionXP += calculateFindingSeedlingXP(s.maturity, s.leafType);
        }
      });

      totalExpeditionXP = Math.max(0, Math.round(totalExpeditionXP));

      const report: ExcursionReportData = {
        safeReturn: !isStranded,
        biomeId: currentBiome.id,
        biomeName: currentBiome.name,
        retentionRate: retention,
        distanceReached: rover.maxDistanceReached,
        batteryRemaining: rover.batteryKwh,
        maxBatteryKwh: rover.maxBatteryKwh,
        totalWeight: getCargoWeight(),
        totalExpeditionXP,
        items: itemBreakdown,
        crystals: crystalBreakdown,
        saplings: saplingBreakdown,
      };

      if (isStranded) {
        gameAudio.playDefeatMotif();
      } else {
        gameAudio.playVictoryFanfare();
      }

      setExcursionReport(report);
    },
    [getCargoWeight],
  );

  // Deposit retained loot into Sanctuary Storage from Report Screen
  const depositHaulAndReturnToSanctuary = useCallback(() => {
    if (!excursionReport) return;

    const inv = sanctuaryInventoryRef.current;
    const report = excursionReport;

    report.items.forEach((item) => {
      inv[item.key] = (inv[item.key] || 0) + item.retained;
    });

    if (report.crystals) {
      if (!inv.crystals) inv.crystals = [];
      report.crystals.forEach((c) => {
        if (c.retained) {
          inv.crystals!.push(c.item);
        }
      });
    }

    inv.scrapMetal = inv.scrap_metal;
    inv.copperWire = inv.copper_wire;
    inv.gears = inv.brass_gears;
    inv.microcircuits = inv.circuit_boards;
    inv.chips = inv.quantumChips = inv.electronic_chips;
    inv.organicWaste = inv.organic_waste;
    inv.enrichedCompost = inv.organic_compost;

    const back = backpackInventoryRef.current;
    report.saplings.forEach((sapReport, idx) => {
      if (sapReport.retained) {
        const sap = back.saplings[idx];
        if (sap) {
          const lType = sap.leafType;
          const mat = sap.maturity || 'sprout';
          recordBondexEntry(lType, mat);

          const uniqueId = (sap as any).id || `seedling_${Date.now()}_${Math.random().toString(36).slice(2, 7)}_${idx}`;
          const pickedNature = (sap as any).nature
            ? getBonsaiNature((sap as any).nature)
            : BONSAI_NATURES[Math.floor(Math.random() * BONSAI_NATURES.length)];
          const bName = getBonsaiDisplayName(lType);
          const seedlingItem: SeedlingItem = {
            id: uniqueId,
            leafType: lType,
            group: sap.group || getLeafTypeDef(lType).group,
            maturity: mat,
            species: lType,
            name: bName,
            rarity: sap.rarity,
            nature: pickedNature,
            color: sap.color || getLeafTypeDef(lType).color,
            flowerColor: sap.flowerColor || getLeafTypeDef(lType).accentColor,
            findOdds: sap.findOdds,
            geneticPotential: (sap as any).geneticPotential || sap.attributes || { ...DEFAULT_BONSAI_ATTRIBUTES },
            attributes: (sap as any).geneticPotential || sap.attributes || { ...DEFAULT_BONSAI_ATTRIBUTES },
            cultivationPotential: sap.cultivationPotential || { ...DEFAULT_CULTIVATION_POTENTIAL },
            discoveredAreaId: (sap as any).discoveredAreaId || report.biomeId,
          };

          if (!sanctuaryInventoryRef.current.seedlingList) {
            sanctuaryInventoryRef.current.seedlingList = [];
          }
          sanctuaryInventoryRef.current.seedlingList.push(seedlingItem);

          storedSaplingsRef.current.push({
            leafType: lType,
            group: sap.group,
            maturity: mat,
            species: lType,
            name: bName,
            rarity: sap.rarity,
            count: 1,
            color: sap.color,
            flowerColor: sap.flowerColor,
            potColor: '#1e293b',
            potStyle: 'Carved Ceramic',
            findOdds: sap.findOdds,
            attributes: seedlingItem.attributes,
            cultivationPotential: sap.cultivationPotential || { ...DEFAULT_CULTIVATION_POTENTIAL },
          });
        }
      }
    });

    // Track completed expeditions per biome
    const biomeKey = report.biomeId;
    statsRef.current.expeditionsPerBiome[biomeKey] =
      (statsRef.current.expeditionsPerBiome[biomeKey] || 0) + 1;

    // Track total items, saplings, and crystals brought back
    const retainedSaplingsCount = report.saplings.filter((s) => s.retained).length;
    const retainedResourcesCount = report.items.reduce((acc, it) => acc + (it.retained || 0), 0);
    const retainedCrystalsCount = report.crystals ? report.crystals.filter((c) => c.retained).length : 0;

    statsRef.current.totalBonsaisBroughtBack = (statsRef.current.totalBonsaisBroughtBack || 0) + retainedSaplingsCount;
    statsRef.current.totalResourcesBroughtBack = (statsRef.current.totalResourcesBroughtBack || 0) + retainedResourcesCount;
    statsRef.current.totalCrystalsBroughtBack = (statsRef.current.totalCrystalsBroughtBack || 0) + retainedCrystalsCount;

    // Award accumulated expedition XP for only the successfully returned cargo
    const securedXP = report.totalExpeditionXP || 0;
    if (securedXP > 0) {
      addPlayerXP(securedXP, 'Excursion Findings');
    }

    backpackInventoryRef.current = {
      scrap_metal: 0,
      copper_wire: 0,
      brass_gears: 0,
      circuit_boards: 0,
      electronic_chips: 0,
      crystals: [],
      saplings: [],
    };

    hasMovedOffSpawnRef.current = false;
    setHasMovedOffSpawn(false);

    setExcursionReport(null);
    setIsBiomeSelectOpen(false);
    setLocation('SANCTUARY');
    locationRef.current = 'SANCTUARY';

    // Strictly restore player's Sanctuary position from before expedition departure
    avatarRef.current.x = sanctuaryPlayerPosRef.current.x;
    avatarRef.current.y = sanctuaryPlayerPosRef.current.y;
    avatarRef.current.facing = 'down';

    // Reset interaction collision references so plots/stations detect immediately
    standingPlotKeyRef.current = '';
    nearbyBonsaiIdRef.current = null;
    nearbyStructureIdRef.current = null;
    isNearZenLibraryRef.current = false;
    isNearWorkbenchRef.current = false;
    isNearBonsaiSocietyRef.current = false;
    isNearGarageRef.current = false;
    isNearShopRef.current = false;
    setNearbyBonsai(null);
    setNearbyStructure(null);
    setStandingPlot(null);
    setActivePlot(null);
    activePlotRef.current = null;

    canvasRef.current?.focus();
    refreshHud();
    gameAudio.playCoinPickup();

    if (securedXP > 0) {
      triggerNotification(`+${securedXP} XP gained from excursion findings! Haul deposited into Sanctuary Storage.`, '#10b981', 4000);
      addFloatingText(sanctuaryPlayerPosRef.current.x, sanctuaryPlayerPosRef.current.y - 45, `+${securedXP} XP from Findings!`, '#38bdf8');
    } else {
      triggerNotification('Haul deposited into Sanctuary Storage!', '#10b981', 3500);
    }

    // Auto-evaluate milestone thresholds
    checkAndAwardMilestones();
  }, [excursionReport, refreshHud, triggerNotification, addPlayerXP, addFloatingText]);

  // Initiate Dig Minigame on Sapling or Crystal (2 BASE STRIKES + 100% SUCCESS REQUIRED)
  const triggerRadialDig = useCallback(
    (node: ExcursionTileNode) => {
      const curWeight = getCargoWeight();
      const maxWeight = getMaxRoverCargo();

      if (node.type === 'CRYSTAL') {
        const cWeight = node.crystalStrength === 1.0 ? 1.0 : 0.5;
        if (curWeight + cWeight > maxWeight) {
          gameAudio.playErrorBuzz();
          triggerNotification(`🎒 Rover Cargo Bed is full (${cWeight}kg needed)! Return to Campsite to unload.`, '#ef4444');
          return;
        }

        const strength = node.crystalStrength || 0.5;
        const totalSpots = strength === 1.0 ? 5 : 3;

        const maxStrikesAllowed = getMaxDigStrikes();
        const isGated = maxStrikesAllowed < totalSpots;

        const baseNormalArc = 0.16 * 2 * Math.PI;
        const speciesFindOdds = 25; // 25% chance for each crystal
        const oddsSizeMult = 1.0 - (33 - speciesFindOdds) * 0.01;

        // Size multiplier for crystals (3 targets for 0.5 -> 0.92, 5 targets for 1.0 -> 0.76)
        const maturitySizeMult = strength === 1.0 ? 0.76 : 0.92;
        const broadSpadeLevel = zenSkillsRef.current.broadSpade || 0;
        const broadSpadeBonus = broadSpadeLevel * 0.05;
        const arcWidth = baseNormalArc * oddsSizeMult * maturitySizeMult * (1 + broadSpadeBonus);
        const arcDeg = (arcWidth * 180) / Math.PI;

        const currentArea = activeBiomeIdRef.current;
        let shovelRotationSpeed: number = AREA_EXCAVATION_SPEEDS.FOOTHILLS;
        if (currentArea === 'HIGHLANDS') shovelRotationSpeed = AREA_EXCAVATION_SPEEDS.HIGHLANDS;
        else if (currentArea === 'OVERGROWTH') shovelRotationSpeed = AREA_EXCAVATION_SPEEDS.OVERGROWTH;

        const sectors: RadialDigState['sectors'] = [];
        const slice = (Math.PI * 2) / totalSpots;
        const effectiveArc = Math.min(arcWidth, slice - 0.06);

        for (let i = 0; i < totalSpots; i++) {
          const maxOffset = Math.max(0, slice - effectiveArc - 0.04);
          const start = i * slice + 0.02 + Math.random() * maxOffset;
          sectors.push({
            startAngle: start,
            arcLength: effectiveArc,
            hit: false,
          });
        }

        const cType = node.crystalType || 'foliage';
        const cTypeLabel =
          cType === 'foliage'
            ? 'Foliage'
            : cType === 'branches'
            ? 'Branch'
            : cType === 'trunk'
            ? 'Trunk'
            : 'Root';

        const crystalItem: CrystalItem = {
          id: `crystal_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`,
          crystalType: cType,
          strength,
          name: `✨ ${cTypeLabel} Crystal (${strength} Strength)`,
          color: node.crystalColor || '#22c55e',
          discoveredAreaId: currentArea,
        };

        digStateRef.current = {
          active: true,
          nodeId: node.id,
          tileX: node.tileX,
          tileY: node.tileY,
          saplingName: `✨ ${cTypeLabel} Crystal (${strength} Strength)`,
          leafType: 'circle',
          group: 'Raundo',
          maturity: 'sprout', // Internal placeholder, UI strictly checks isCrystal
          species: cType,
          rarity: strength === 1.0 ? 'RARE' : 'UNCOMMON',
          needleAngle: 0,
          angularVelocity: shovelRotationSpeed,
          sectors,
          requiredHits: totalSpots,
          currentHits: 0,
          strikesUsed: 0,
          maxStrikes: maxStrikesAllowed,
          isGated,
          wobbleTimer: 0,
          status: 'DIGGING',
          speciesChance: 0.25,
          arcDeg,
          isCrystal: true,
          crystalItem,
        };

        gameAudio.playPowerupChime();
        if (isGated) {
          gameAudio.playErrorBuzz();
          triggerNotification(`⚠️ Requires ${totalSpots} Strikes (Current: ${maxStrikesAllowed})! Upgrade Careful Trowel in Zen Skills.`, '#f59e0b');
        }
        return;
      }

      if (curWeight + ITEM_WEIGHTS.sapling > maxWeight) {
        gameAudio.playErrorBuzz();
        triggerNotification('🎒 Rover Cargo Bed is full (3.0kg)! Return to Campsite to unload.', '#ef4444');
        return;
      }

      const leafType: BonsaiLeafType = node.saplingLeafType || 'circle';
      const leafDef = getLeafTypeDef(leafType);
      const group: BonsaiGroup = node.saplingGroup || leafDef.group;
      const maturity: MaturityTier = node.saplingMaturity || 'sprout';
      const matDef = getMaturityDef(maturity);
      const rarity = node.saplingRarity || leafDef.rarity;

      // Number of digging zones: Rating 1: 2 zones, Rating 2: 3 zones, Rating 3: 4 zones, Rating 4: 5 zones, Rating 5: 6 zones (zonesCount = maturity + 1)
      const matRank = matDef.rank; // 1 to 5
      const totalSpots = MATURITY_SPOTS_COUNT[maturity] || (matRank + 1);

      const maxStrikesAllowed = getMaxDigStrikes(); // Base 2 + Careful Trowel ranks
      const isGated = maxStrikesAllowed < totalSpots; // Cannot win without enough strikes!

      // Digging Arc Calculation:
      // Base normal (100% size) digging area width = 16% of the full circle (0.16 * 2 * Math.PI radians, or 57.6°)
      const baseNormalArc = 0.16 * 2 * Math.PI;

      // Species Find Odds scaling:
      // 33% odds = 100% (1.0). Each 1% less in odds reduces digging area size by 1%:
      // oddsSizeMult = 1.0 - (33 - speciesFindOdds) * 0.01 (e.g., 1% odds -> 1.0 - 0.32 = 0.68)
      const rawOdds = node.findOdds ?? Math.round(getSpeciesAreaProbability(activeBiomeIdRef.current, leafType) * 100);
      const speciesFindOdds = Math.max(1, Math.min(33, rawOdds));
      const oddsSizeMult = 1.0 - (33 - speciesFindOdds) * 0.01;

      // Maturity Rating scaling:
      // Rating 1: 100% (1.00), Rating 2: 92% (0.92), Rating 3: 84% (0.84), Rating 4: 76% (0.76), Rating 5: 68% (0.68)
      const maturitySizeMultMap: Record<number, number> = {
        1: 1.00,
        2: 0.92,
        3: 0.84,
        4: 0.76,
        5: 0.68,
      };
      const maturitySizeMult = maturitySizeMultMap[matRank] ?? Math.max(0.68, 1.00 - (matRank - 1) * 0.08);

      // Broad Spade skill bonus: +5% arc width per level (+25% max at level 5)
      const broadSpadeLevel = zenSkillsRef.current.broadSpade || 0;
      const broadSpadeBonus = broadSpadeLevel * 0.05;

      // Combined arc width = (0.16 * 2 * Math.PI) * oddsSizeMult * maturitySizeMult * (1 + broadSpadeBonus)
      const arcWidth = baseNormalArc * oddsSizeMult * maturitySizeMult * (1 + broadSpadeBonus);
      const arcDeg = (arcWidth * 180) / Math.PI;

      // Shovel rotation speed by expedition area:
      // Area 1 (Sunlit Foothills): ~3.2 rad/s
      // Area 2 (Misty Highlands): ~4.4 rad/s
      // Area 3 (Ancient Caldera): ~5.8 rad/s
      const currentArea = activeBiomeIdRef.current;
      let shovelRotationSpeed: number = AREA_EXCAVATION_SPEEDS.FOOTHILLS;
      if (currentArea === 'HIGHLANDS') {
        shovelRotationSpeed = AREA_EXCAVATION_SPEEDS.HIGHLANDS;
      } else if (currentArea === 'OVERGROWTH') {
        shovelRotationSpeed = AREA_EXCAVATION_SPEEDS.OVERGROWTH;
      }

      // 100% Hit Requirement: requiredHits EQUALS totalSpots!
      const reqHits = totalSpots;

      // Distribute targetCount = targetMaturity + 1 targets around the circle without overlapping
      const sectors: RadialDigState['sectors'] = [];
      const slice = (Math.PI * 2) / totalSpots;
      const effectiveArc = Math.min(arcWidth, slice - 0.06);

      for (let i = 0; i < totalSpots; i++) {
        const maxOffset = Math.max(0, slice - effectiveArc - 0.04);
        const start = i * slice + 0.02 + Math.random() * maxOffset;
        sectors.push({
          startAngle: start,
          arcLength: effectiveArc,
          hit: false,
        });
      }

      digStateRef.current = {
        active: true,
        nodeId: node.id,
        tileX: node.tileX,
        tileY: node.tileY,
        saplingName: node.saplingName || getBonsaiDisplayName(leafType),
        leafType,
        group,
        maturity,
        species: leafType,
        rarity,
        needleAngle: 0,
        angularVelocity: shovelRotationSpeed,
        sectors,
        requiredHits: reqHits,
        currentHits: 0,
        strikesUsed: 0,
        maxStrikes: maxStrikesAllowed,
        isGated,
        wobbleTimer: 0,
        status: 'DIGGING',
        speciesChance: speciesFindOdds / 100,
        arcDeg,
      };

      // Reveal species in Rover Garage Codex and Bondex immediately upon excavation initiation
      revealAreaSpecies(activeBiomeIdRef.current, leafType, maturity);

      if (isGated) {
        gameAudio.playErrorBuzz();
        triggerNotification(`⚠️ Requires ${totalSpots} Strikes (Current: ${maxStrikesAllowed})! Upgrade Careful Trowel in Zen Skills.`, '#f59e0b');
      } else {
        gameAudio.playPowerupChime();
      }
    },
    [getCargoWeight, getMaxDigStrikes, getMaxRoverCargo, triggerNotification],
  );

  // Discrete Grid Step Movement for Rover
  const attemptRoverStep = useCallback(
    (dx: number, dy: number) => {
      if (locationRef.current !== 'EXCURSION' || digStateRef.current.active || excursionReport || excavationResult) return;

      const rover = roverRef.current;
      const currentBiome = EXPEDITION_BIOMES[activeBiomeIdRef.current];
      const stepCost = currentBiome.batteryCostPerStep;

      if (rover.batteryKwh <= 0) {
        finishExcursion(true);
        return;
      }

      const nextTileX = rover.tileX + dx;
      const nextTileY = rover.tileY + dy;
      const targetDist = Math.hypot(nextTileX, nextTileY);

      // Maximum Unlocked Distance Barrier for Area
      const maxAllowedSteps = getMaxAllowedStepsForArea(activeBiomeIdRef.current, sanctuaryInventoryRef.current);
      if (targetDist > maxAllowedSteps) {
        gameAudio.playErrorBuzz();
        triggerNotification(`Requires Expansion Map to travel beyond ${maxAllowedSteps} steps`, '#f43f5e');
        return;
      }

      rover.tileX = nextTileX;
      rover.tileY = nextTileY;
      rover.stepsTaken = (rover.stepsTaken || 0) + 1;

      if (nextTileX !== 0 || nextTileY !== 0) {
        if (!hasMovedOffSpawnRef.current) {
          hasMovedOffSpawnRef.current = true;
          rover.hasMovedOffSpawn = true;
          setHasMovedOffSpawn(true);
        }
      }

      // Perpetuum Mobile check (0% at Lv.0, +5% per rank up to 25% total at Lv.5)
      const perpetuumRank = zenSkillsRef.current.perpetuum_mobile || 0;
      const perpetuumChance = perpetuumRank * 0.05;
      const isFreeEnergy = perpetuumChance > 0 && Math.random() < perpetuumChance;

      if (!isFreeEnergy) {
        rover.batteryKwh = Math.max(0, rover.batteryKwh - stepCost);
      } else {
        addFloatingText(rover.visualX, rover.visualY - 25, '⚡ 0 Energy (Perpetuum Mobile!)', '#38bdf8');
      }

      // Reveal fog around new rover position
      revealFogAroundRover(nextTileX, nextTileY);

      if (dx > 0) {
        rover.facing = 'right';
        rover.facingDirection = 1;
      } else if (dx < 0) {
        rover.facing = 'left';
        rover.facingDirection = -1;
      } else if (dy > 0) {
        rover.facing = 'down';
      } else if (dy < 0) {
        rover.facing = 'up';
      }

      const currentDist = Math.round(Math.hypot(rover.tileX, rover.tileY));
      rover.maxDistanceReached = Math.max(rover.maxDistanceReached, currentDist);

      gameAudio.playFootstepWood();

      if (rover.tileX === 0 && rover.tileY === 0) {
        if (hasMovedOffSpawnRef.current) {
          triggerNotification('🏕️ At Campsite Base! Click [Unload Haul] or press [Enter] to safely return with 100% loot.', '#10b981');
        } else {
          triggerNotification('🏕️ At Campsite Base! Explore the sector before returning to sanctuary.', '#f59e0b');
        }
      }

      const node = findNearbyExcursionNode();

      if (node && !node.collected) {
        if (node.type === 'RESOURCE' && node.resourceType) {
          const rt = node.resourceType;
          const curArea = activeBiomeIdRef.current;
          const disc = areaDiscoveryRef.current;
          if (!disc.resources[curArea].includes(rt)) {
            disc.resources[curArea].push(rt);
          }
          const yieldCount = node.resourceYield || (
            rt === 'scrap_metal_triple' || rt === 'copper_wire_triple' ? 3 :
            rt === 'scrap_metal_double' || rt === 'copper_wire_double' || rt === 'brass_gears_double' || rt === 'circuit_boards_double' ? 2 : 1
          );
          const baseKey = (
            rt === 'scrap_metal_double' || rt === 'scrap_metal_triple' ? 'scrap_metal' :
            rt === 'copper_wire_double' || rt === 'copper_wire_triple' ? 'copper_wire' :
            rt === 'brass_gears_double' ? 'brass_gears' :
            rt === 'circuit_boards_double' ? 'circuit_boards' : rt
          ) as ResourceItemKey;
          const singleWeight = ITEM_WEIGHTS[baseKey] || 0.8;
          const totalWeight = singleWeight * yieldCount;
          const curWeight = getCargoWeight();
          const maxWeight = getMaxRoverCargo();

          const nameMap: Record<string, string> = {
            scrap_metal: '🔩 Scrap Metal',
            copper_wire: '⚡ Copper Wire',
            brass_gears: '⚙️ Brass Gear',
            circuit_boards: '🟩 Circuit Board',
            electronic_chips: '💎 Electronic Chip',
            scrap_metal_double: '🔩 Heavy Scrap Metal Cache (2x)',
            copper_wire_double: '⚡ Heavy Copper Wire Bundle (2x)',
            scrap_metal_triple: '🔩 Scrap Metal Trio (3x)',
            copper_wire_triple: '⚡ Copper Wire Spools (3x)',
            brass_gears_double: '⚙️ Interlocking Brass Gears (2x)',
            circuit_boards_double: '🟩 Layered Microcircuits (2x)',
          };

          const label = yieldCount > 1 && !rt.includes('double')
            ? `${nameMap[baseKey]} (${yieldCount}x, ${totalWeight.toFixed(1)}kg)`
            : `${nameMap[rt] || rt} (${totalWeight.toFixed(1)}kg)`;

          if (curWeight + totalWeight <= maxWeight) {
            triggerNotification(`Found ${label}! Press [E] to collect.`, '#38bdf8');
          } else {
            triggerNotification(`Found ${label}! [Backpack Full - Return to Base]`, '#ef4444');
          }
        } else if (node.type === 'SAPLING') {
          const curWeight = getCargoWeight();
          const maxWeight = getMaxRoverCargo();
          const dName = getBonsaiDisplayName(node.saplingLeafType || node.saplingSpecies);
          if (curWeight + ITEM_WEIGHTS.sapling <= maxWeight) {
            triggerNotification(`Found ${dName}! Press [E] to Excavate (3.0kg).`, '#34d399');
          } else {
            triggerNotification(`Found ${dName}! [Backpack Full (3.0kg)]`, '#ef4444');
          }
        } else if (node.type === 'CRYSTAL') {
          const curWeight = getCargoWeight();
          const maxWeight = getMaxRoverCargo();
          const cWeight = node.crystalStrength === 1.0 ? 1.0 : 0.5;
          const cType = node.crystalType || 'foliage';
          const cTypeLabel =
            cType === 'foliage'
              ? 'Foliage'
              : cType === 'branches'
              ? 'Branch'
              : cType === 'trunk'
              ? 'Trunk'
              : 'Root';
          if (curWeight + cWeight <= maxWeight) {
            triggerNotification(`Found Glowing ✨ ${cTypeLabel} Crystal (${node.crystalStrength} Strength)! Press [E] to Excavate (${cWeight}kg).`, node.crystalColor || '#38bdf8');
          } else {
            triggerNotification(`Found Glowing ✨ ${cTypeLabel} Crystal (${node.crystalStrength} Strength)! [Backpack Full (${curWeight}/${maxWeight}kg)]`, '#ef4444');
          }
        }
      }

      if (rover.batteryKwh <= 0) {
        if (rover.tileX === 0 && rover.tileY === 0 && hasMovedOffSpawnRef.current) {
          finishExcursion(false);
        } else {
          finishExcursion(true);
        }
      }

      refreshHud();
    },
    [excursionReport, finishExcursion, getCargoWeight, getMaxRoverCargo, refreshHud, triggerNotification, addFloatingText, revealFogAroundRover],
  );

  // Claim Zen Milestone Achievement
  const claimAchievement = useCallback(
    (achId: string, rewardZen: number, title: string) => {
      const stats = statsRef.current;
      if (stats.claimedAchievements.includes(achId)) return;
      stats.claimedAchievements.push(achId);
      sanctuaryInventoryRef.current.zen_essence += rewardZen;
      gameAudio.playLevelUpStinger();
      addFloatingText(canvasWidth / 2, canvasHeight / 2, `🏆 +${rewardZen} Zen Points!`, '#ec4899');
      triggerNotification(`🏆 Claimed "${title}"! (+${rewardZen} Zen Points)`, '#ec4899');
      refreshHud();
    },
    [addFloatingText, canvasHeight, canvasWidth, refreshHud, triggerNotification],
  );

  // Automatic Milestone Evaluation & Payout
  const checkAndAwardMilestones = useCallback(() => {
    const stats = statsRef.current;
    const inv = sanctuaryInventoryRef.current;
    if (!stats || !inv) return;

    let totalAwarded = 0;
    let lastTitle = '';
    let lastTier = '';

    SOCIETY_MILESTONES.forEach((ms) => {
      if (ms.isNotObtainable) return;

      const curVal = ms.getValue(
        stats,
        bondexDiscoveryRef.current,
        plantedBonsaisRef.current,
        storedPottedBonsaisRef.current,
        inv,
      );
      const claimed = stats.claimedMilestoneBlocks?.[ms.id] || [];

      for (let t = 0; t < 5; t++) {
        const threshold = ms.targets[t];
        if (curVal >= threshold && !claimed.includes(t)) {
          claimed.push(t);
          const reward = BLOCK_REWARDS[t];
          totalAwarded += reward;
          lastTitle = ms.title;
          lastTier = TIER_LABELS[t];
        }
      }

      if (!stats.claimedMilestoneBlocks) stats.claimedMilestoneBlocks = {};
      stats.claimedMilestoneBlocks[ms.id] = claimed;
    });

    if (totalAwarded > 0) {
      gameAudio?.playLevelUpStinger?.();
      addPlayerXP(totalAwarded, `Milestone: ${lastTitle}`);
      triggerNotification(
        `🏆 Milestone Block Reached: ${lastTitle} (Block ${lastTier})! (+${totalAwarded} XP)`,
        '#10b981',
        3500,
      );
      refreshHud();
    }
  }, [addPlayerXP, refreshHud, triggerNotification]);

  // --- SAVE / LOAD SYSTEM & PAYLOAD BUILDER ---
  const buildSavePayload = useCallback((): Omit<FullSaveState, 'metadata'> => {
    return {
      gameState: { ...gameStateRef.current },
      plantedBonsais: JSON.parse(JSON.stringify(plantedBonsaisRef.current)),
      deployedStructures: JSON.parse(JSON.stringify(deployedStructuresRef.current)),
      storedPottedBonsais: JSON.parse(JSON.stringify(storedPottedBonsaisRef.current)),
      storedSaplings: JSON.parse(JSON.stringify(storedSaplingsRef.current)),
      sanctuaryInventory: JSON.parse(JSON.stringify(sanctuaryInventoryRef.current)),
      zenSkills: JSON.parse(JSON.stringify(zenSkillsRef.current)),
      stats: JSON.parse(JSON.stringify(statsRef.current)),
      bondexDiscovery: JSON.parse(JSON.stringify(bondexDiscoveryRef.current)),
      areaDiscovery: JSON.parse(JSON.stringify(areaDiscoveryRef.current)),
      installedCraftingArms: installedCraftingArmsRef.current,
      autoFabricatorLanes: JSON.parse(JSON.stringify(autoFabricatorLanesRef.current)),
      globalAutoUnloaderSettings: JSON.parse(JSON.stringify(globalAutoUnloaderSettingsRef.current)),
      globalCareDispenserLimits: JSON.parse(JSON.stringify(globalCareDispenserLimitsRef.current)),
      masterQuests: JSON.parse(JSON.stringify(masterQuestsRef.current)),
      activeCrafting: activeCraftingRef.current ? JSON.parse(JSON.stringify(activeCraftingRef.current)) : null,
      craftingQueue: JSON.parse(JSON.stringify(craftingQueueRef.current)),
      avatarPos: { x: avatarRef.current.x, y: avatarRef.current.y },
    };
  }, []);

  const handleSaveGame = useCallback(
    (slot: SaveSlotId, isSilent = false) => {
      const payload = buildSavePayload();
      const meta = saveGame(slot, payload);
      setCurrentActiveSaveSlot(slot);

      if (!isSilent) {
        gameAudio?.playConfirmSelect?.();
        const slotLabel = slot === 'autosave' ? 'Autosave Slot' : `Manual Slot ${slot}`;
        triggerNotification(`💾 Game successfully saved to ${slotLabel}!`, '#10b981', 3000);
      }
      return meta;
    },
    [buildSavePayload, triggerNotification],
  );

  const applyLoadedSave = useCallback(
    (loaded: { fullState: FullSaveState; elapsedSeconds: number; offlineSummary?: OfflineSummary }, slotId: SaveSlotId) => {
      const fs = loaded.fullState;

      plantedBonsaisRef.current = fs.plantedBonsais || [];
      deployedStructuresRef.current = fs.deployedStructures || [];
      storedPottedBonsaisRef.current = fs.storedPottedBonsais || [];
      storedSaplingsRef.current = fs.storedSaplings || [];
      sanctuaryInventoryRef.current = fs.sanctuaryInventory || sanctuaryInventoryRef.current;
      zenSkillsRef.current = fs.zenSkills || zenSkillsRef.current;
      statsRef.current = fs.stats || statsRef.current;
      bondexDiscoveryRef.current = fs.bondexDiscovery || {};
      areaDiscoveryRef.current = fs.areaDiscovery || {
        species: { FOOTHILLS: [], HIGHLANDS: [], OVERGROWTH: [] },
        maturities: { FOOTHILLS: [], HIGHLANDS: [], OVERGROWTH: [] },
        resources: { FOOTHILLS: [], HIGHLANDS: [], OVERGROWTH: [] },
      };
      installedCraftingArmsRef.current = fs.installedCraftingArms || 0;
      autoFabricatorLanesRef.current = fs.autoFabricatorLanes || [];
      globalAutoUnloaderSettingsRef.current = fs.globalAutoUnloaderSettings || DEFAULT_AUTO_UNLOADER_SETTINGS;
      setGlobalAutoUnloaderSettings(globalAutoUnloaderSettingsRef.current);
      globalCareDispenserLimitsRef.current = fs.globalCareDispenserLimits || DEFAULT_CARE_DISPENSER_LIMITS;
      setGlobalCareDispenserLimits(globalCareDispenserLimitsRef.current);
      masterQuestsRef.current = fs.masterQuests || masterQuestsRef.current;
      activeCraftingRef.current = fs.activeCrafting || null;
      craftingQueueRef.current = fs.craftingQueue || [];

      if (fs.avatarPos) {
        avatarRef.current.x = fs.avatarPos.x;
        avatarRef.current.y = fs.avatarPos.y;
        sanctuaryPlayerPosRef.current = { x: fs.avatarPos.x, y: fs.avatarPos.y };
      }

      setCurrentActiveSaveSlot(slotId);
      setLocation('SANCTUARY');
      locationRef.current = 'SANCTUARY';

      setGameState({
        status: 'PLAYING',
        score: fs.gameState?.score || 0,
        level: fs.gameState?.level || 1,
        masterQuest: masterQuestsRef.current,
        masterQuests: masterQuestsRef.current,
      });

      offscreenTerrainDirtyRef.current = true;
      invalidateSynergiesCache();
      refreshHud();
      refreshMasterQuests();

      gameAudio?.playPowerupChime?.();
      const slotLabel = slotId === 'autosave' ? 'Autosave Slot' : `Manual Slot ${slotId}`;
      triggerNotification(`📂 Loaded ${slotLabel}!`, '#38bdf8', 3500);

      // Check if offline progression occurred
      if (loaded.offlineSummary && loaded.elapsedSeconds >= 10) {
        setOfflineSummaryData(loaded.offlineSummary);
        setOfflineSummaryModalOpen(true);
      }
    },
    [invalidateSynergiesCache, refreshHud, refreshMasterQuests, triggerNotification],
  );

  const handleLoadGame = useCallback(
    (slot: SaveSlotId) => {
      const result = loadGame(slot);
      if (!result) {
        gameAudio?.playErrorBuzz?.();
        triggerNotification(`Save slot ${slot} is empty or unreadable!`, '#ef4444');
        return;
      }
      applyLoadedSave(result, slot);
    },
    [applyLoadedSave, triggerNotification],
  );

  const handleDeleteSaveSlot = useCallback(
    (slot: SaveSlotId) => {
      const success = deleteSaveSlot(slot);
      if (success) {
        gameAudio?.playCrispClick?.();
        const slotLabel = slot === 'autosave' ? 'Autosave Slot' : `Slot ${slot}`;
        triggerNotification(`Cleared ${slotLabel}.`, '#f59e0b', 3000);
        refreshHud();
      }
    },
    [refreshHud, triggerNotification],
  );

  // Autosave interval every 30 seconds while playing
  useEffect(() => {
    const timer = setInterval(() => {
      if (gameStateRef.current.status === 'PLAYING') {
        handleSaveGame('autosave', true);
      }
    }, 30000);
    return () => clearInterval(timer);
  }, [handleSaveGame]);

  // Initialize or Restart Game
