  // Title Screen Keyboard and Menu Navigation
  useEffect(() => {
    if (gameState.status !== 'START') return;

    const maxItems = hasExistingSave ? 4 : 3;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'w' || e.key === 'W') {
        e.preventDefault();
        setTitleMenuIdx((i) => Math.max(0, i - 1));
        gameAudio.playHoverMicroTone();
      } else if (e.key === 's' || e.key === 'S') {
        e.preventDefault();
        setTitleMenuIdx((i) => Math.min(maxItems, i + 1));
        gameAudio.playHoverMicroTone();
      } else if (e.key === 'e' || e.key === 'E' || e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        if (hasExistingSave) {
          if (titleMenuIdx === 0) {
            handleLoadGame('autosave');
            if (sdk) sdk.startGame();
          } else if (titleMenuIdx === 1) {
            initGame();
            if (sdk) sdk.startGame();
          } else if (titleMenuIdx === 2) {
            setIsSaveLoadModalOpen(true);
            gameAudio.playCrispClick();
          } else if (titleMenuIdx === 3) {
            setIsHowToPlayOpen(true);
            gameAudio.playCrispClick();
          } else if (titleMenuIdx === 4) {
            setIsGameMenuOpen(true);
            gameAudio.playCrispClick();
          }
        } else {
          if (titleMenuIdx === 0) {
            setGameState((prev) => ({...prev, status: 'PLAYING'}));
            gameAudio.playPowerupChime();
            if (sdk) sdk.startGame();
          } else if (titleMenuIdx === 1) {
            setIsSaveLoadModalOpen(true);
            gameAudio.playCrispClick();
          } else if (titleMenuIdx === 2) {
            setIsHowToPlayOpen(true);
            gameAudio.playCrispClick();
          } else if (titleMenuIdx === 3) {
            setIsGameMenuOpen(true);
            gameAudio.playCrispClick();
          }
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [gameState.status, titleMenuIdx, hasExistingSave, sdk, handleLoadGame, initGame]);

  // Cancel Digging Minigame safely without spending strikes or failing
  const cancelDiggingMinigame = useCallback(() => {
    if (!digStateRef.current.active) return;
    if (!digStateRef.current.isCrystal) {
      revealAreaSpecies(activeBiomeIdRef.current, digStateRef.current.leafType, digStateRef.current.maturity);
    }
    digStateRef.current.active = false;
    digStateRef.current.status = 'DIGGING';
    gameAudio.playCrispClick();
    triggerNotification('Left excavation site safely without spending strikes.', '#94a3b8');
    refreshHud();
  }, [revealAreaSpecies, refreshHud, triggerNotification]);

  // Helper to locate active/anomaly site strictly at current tile
  const findNearbyExcursionNode = useCallback(() => {
    const rover = roverRef.current;
    const currentKey = `${rover.tileX},${rover.tileY}`;
    const exactNode = excursionNodesRef.current.get(currentKey);
    if (exactNode && !exactNode.collected) return exactNode;
    return null;
  }, []);

  // Voluntary Harvest of Resource Node at Rover Tile
  const collectCurrentRoverResource = useCallback(() => {
    if (locationRef.current !== 'EXCURSION' || digStateRef.current.active || excursionReport || excavationResult) return;
    const node = findNearbyExcursionNode();

    if (node && !node.collected && node.type === 'RESOURCE' && node.resourceType) {
      const rt = node.resourceType;
      const yieldCount = node.resourceYield || (
        rt === 'scrap_metal_triple' || rt === 'copper_wire_triple' ? 3 :
        rt === 'scrap_metal_double' || rt === 'copper_wire_double' || rt === 'brass_gears_double' || rt === 'circuit_boards_double' ? 2 : 1
      );
      const baseKey = (
        rt === 'scrap_metal_double' || rt === 'scrap_metal_triple' ? 'scrap_metal' :
        rt === 'copper_wire_double' || rt === 'copper_wire_triple' ? 'copper_wire' :
        rt === 'brass_gears_double' ? 'brass_gears' :
        rt === 'circuit_boards_double' ? 'circuit_boards' : rt
      ) as ResourceItemKey;
      const singleWeight = ITEM_WEIGHTS[baseKey] || 0.8;
      const totalWeight = singleWeight * yieldCount;
      const curWeight = getCargoWeight();
      const maxWeight = getMaxRoverCargo();

      if (curWeight + totalWeight <= maxWeight) {
        node.collected = true;
        backpackInventoryRef.current[baseKey] += yieldCount;
        gameAudio.playCoinPickup();

        // Track discovered resource in current area codex
        const curArea = activeBiomeIdRef.current;
        const disc = areaDiscoveryRef.current;
        if (!disc.resources[curArea].includes(rt)) {
          disc.resources[curArea].push(rt);
        }

        const nameMap: Record<string, string> = {
          scrap_metal: '🔩 Scrap Metal',
          copper_wire: '⚡ Copper Wire',
          brass_gears: '⚙️ Brass Gear',
          circuit_boards: '🟩 Circuit Board',
          electronic_chips: '💎 Electronic Chip',
          scrap_metal_double: '🔩 Heavy Scrap Metal Cache (2x)',
          copper_wire_double: '⚡ Heavy Copper Wire Bundle (2x)',
          scrap_metal_triple: '🔩 Scrap Metal Trio (3x)',
          copper_wire_triple: '⚡ Copper Wire Spools (3x)',
          brass_gears_double: '⚙️ Interlocking Brass Gears (2x)',
          circuit_boards_double: '🟩 Layered Microcircuits (2x)',
        };
        const label = yieldCount > 1 && !rt.includes('double')
          ? `${nameMap[baseKey]} (${yieldCount}x, ${totalWeight.toFixed(1)}kg)`
          : `${nameMap[rt] || rt} (${totalWeight.toFixed(1)}kg)`;

        triggerNotification(`Harvested ${label}! Secured in cargo bed.`, '#f59e0b');
        refreshHud();
      } else {
        gameAudio.playErrorBuzz();
        triggerNotification(`🎒 Rover Cargo Bed full! (${totalWeight.toFixed(1)}kg needed) Return to Campsite to unload.`, '#ef4444');
      }
    }
  }, [excursionReport, gainPlayerExp, getCargoWeight, getMaxRoverCargo, refreshHud, triggerNotification]);
  useEffect(() => {
    if (
      !hasAutoplayed.current &&
      new URLSearchParams(window.location.search).has('autoplay')
    ) {
      hasAutoplayed.current = true;
      initGame();
    }
  }, [initGame]);

  // Handle Victory fanfare
  useEffect(() => {
    if (gameState.status === 'VICTORY') {
      gameAudio.playVictoryFanfare();
    }
  }, [gameState.status]);

  // Helper to calculate discounted price using Discount Hunter skill (-2% per rank)
  const getDiscountedCost = useCallback((baseCost: number) => {
    const discountHunterLvl =
      zenSkillsRef.current.discountHunter ||
      (zenSkillsRef.current as any)['discount_hunter'] ||
      0;
    const discountMultiplier = Math.max(0.1, 1 - discountHunterLvl * 0.02);
    return Math.max(1, Math.round(baseCost * discountMultiplier));
  }, []);

  // --- ECONOMY: PURCHASE CARTOGRAPHY MAPS ---
  const buyExpeditionMap = useCallback(
    (mapKey: string, cost: number, mapName: string) => {
      const inv = sanctuaryInventoryRef.current;
      if (!inv.unlockedMaps) inv.unlockedMaps = ['area1_base'];
      if (inv.unlockedMaps.includes(mapKey) || inv[mapKey]) return;

      const effectiveCost = getDiscountedCost(cost);
      if (inv.coins >= effectiveCost) {
        inv.coins = Number((inv.coins - effectiveCost).toFixed(2));
        inv[mapKey] = true;
        if (!inv.unlockedMaps.includes(mapKey)) {
          inv.unlockedMaps.push(mapKey);
        }
        if (mapKey === 'area2_base') {
          inv.has_map_highlands = true;
        }
        if (mapKey === 'area3_base') {
          inv.has_map_overgrowth = true;
        }
        gameAudio.playLevelUpStinger();
        triggerNotification(`🗺️ Charted ${mapName}! Expanded wilderness territory!`, '#38bdf8');
        refreshHud();
      } else {
        gameAudio.playErrorBuzz();
        triggerNotification(`Need ${effectiveCost} Verdure to purchase ${mapName}! Donate mature bonsais.`, '#ef4444');
      }
    },
    [getDiscountedCost, refreshHud, triggerNotification],
  );

  // --- ECONOMY: PURCHASE SANCTUARY GREENHOUSE EXPANSIONS (STRICTLY SEQUENTIAL) ---
  const buySanctuaryExpansion = useCallback(
    (targetTier: number, cost: number, name: string) => {
      const inv = sanctuaryInventoryRef.current;
      if (inv.sanctuary_expansion_tier >= targetTier) return;
      if (targetTier > (inv.sanctuary_expansion_tier || 0) + 1) {
        gameAudio.playErrorBuzz();
        triggerNotification('Must purchase previous expansion tier first!', '#ef4444');
        return;
      }

      const effectiveCost = getDiscountedCost(cost);
      if (inv.coins >= effectiveCost) {
        inv.coins = Number((inv.coins - effectiveCost).toFixed(2));
        inv.sanctuary_expansion_tier = targetTier;
        offscreenTerrainDirtyRef.current = true;
        invalidateSynergiesCache();
        gameAudio.playPowerupChime();
        triggerNotification(`🏡 Expanded Sanctuary! ${name} unlocked!`, '#10b981');
        refreshHud();
      } else {
        gameAudio.playErrorBuzz();
        triggerNotification(`Need ${effectiveCost} Verdure to purchase ${name}! Donate cultivated trees.`, '#ef4444');
      }
    },
    [getDiscountedCost, refreshHud, triggerNotification],
  );

  // --- ECOLOGICAL RESTORATION: DONATE BONSAI (PLANTED OR STORED) ---
  const donatePlantedBonsai = useCallback(
    (bonsaiId: string) => {
      const bonsaiIdx = plantedBonsaisRef.current.findIndex((b) => b.id === bonsaiId);
      if (bonsaiIdx === -1) return;

      const bonsai = plantedBonsaisRef.current[bonsaiIdx];
      if (bonsai.isFavorite) {
        gameAudio.playErrorBuzz();
        triggerNotification('Cannot donate: Bonsai is Favorited! Unfavorite to unlock donation.', '#ef4444');
        return;
      }

      // Base payout includes Expert Negotiator skill (+10%/lvl) and is floored to 2 decimals
      const basePayout = calculateDonationValue(bonsai, zenSkillsRef.current);

      // Check Eco Quest active Botanical Request matching
      const eco = masterQuestsRef.current.eco;
      const match = checkMatchesEcoRequest(bonsai, eco.activeRequestIndex, eco.requestCounts);
      const isMatch = match.matches;
      const finalPayout = isMatch ? Math.floor((basePayout * 2 + 1e-9) * 100) / 100 : basePayout;

      const inv = sanctuaryInventoryRef.current;
      if (bonsai.automatonTier > 0) {
        const oldKey =
          bonsai.automatonTier === 1
            ? 'automatons_tier1'
            : bonsai.automatonTier === 2
            ? 'automatons_tier2'
            : 'automatons_tier3';
        inv[oldKey] += 1;
      }

      inv.coins = Number((inv.coins + finalPayout).toFixed(2));
      plantedBonsaisRef.current.splice(bonsaiIdx, 1);
      invalidateSynergiesCache();

      if (isMatch && match.key) {
        eco.requestCounts[match.key] = (eco.requestCounts[match.key] || 0) + 1;
        if (isEcoRequestComplete(eco.activeRequestIndex, eco.requestCounts)) {
          const finishedNum = eco.activeRequestIndex + 1;
          eco.completedRequests = Math.min(10, eco.completedRequests + 1);
          eco.activeRequestIndex = Math.min(10, eco.activeRequestIndex + 1);
          eco.requestCounts = {};
          gameAudio.playVictoryFanfare();
          triggerNotification(
            `🎉 Eco Request #${finishedNum} Completed!${finishedNum < 10 ? ` (Advanced to Request #${finishedNum + 1})` : ' (All 10 Requests Finished - Complete Rank 1 at Bonsai Society!)'}`,
            '#facc15',
            4500,
          );
        } else {
          gameAudio.playPowerupChime();
          triggerNotification(
            `🌟 Eco Request Progress! (+${finalPayout.toFixed(2)} Verdure - 2x Bonus)`,
            '#34d399',
            3500,
          );
        }
        refreshMasterQuests();
      } else {
        gameAudio.playCoinPickup();
        triggerNotification(
          `🌱 Donated ${getBonsaiDisplayName(bonsai)} (Lv.${bonsai.level}) to ecological restoration for +${finalPayout.toFixed(2)} Verdure!${bonsai.automatonTier > 0 ? ' (Automaton returned to inventory)' : ''}`,
          '#10b981',
        );
      }

      addFloatingText(
        bonsai.x,
        bonsai.y - 50,
        `+${finalPayout.toFixed(2)} Verdure!${isMatch ? ' (🌟 2x Eco Match)' : ''}`,
        isMatch ? '#facc15' : '#34d399',
      );

      if (inspectingBonsaiId === bonsaiId) {
        setInspectingBonsaiId(null);
      }
      refreshHud();
    },
    [addFloatingText, inspectingBonsaiId, refreshHud, refreshMasterQuests, triggerNotification],
  );
  const sellPlantedBonsai = donatePlantedBonsai;

  const donateStoredPottedBonsai = useCallback(
    (storedId: string) => {
      const idx = storedPottedBonsaisRef.current.findIndex((b) => b.id === storedId);
      if (idx === -1) return;

      const bonsai = storedPottedBonsaisRef.current[idx];
      if (bonsai.isFavorite) {
        gameAudio.playErrorBuzz();
        triggerNotification('Cannot donate: Bonsai is Favorited! Unfavorite to unlock donation.', '#ef4444');
        return;
      }

      // Base payout includes Expert Negotiator skill (+10%/lvl) and is floored to 2 decimals
      const basePayout = calculateDonationValue(bonsai, zenSkillsRef.current);

      // Check Eco Quest active Botanical Request matching
      const eco = masterQuestsRef.current.eco;
      const match = checkMatchesEcoRequest(bonsai, eco.activeRequestIndex, eco.requestCounts);
      const isMatch = match.matches;
      const finalPayout = isMatch ? Math.floor((basePayout * 2 + 1e-9) * 100) / 100 : basePayout;

      sanctuaryInventoryRef.current.coins = Number(
        (sanctuaryInventoryRef.current.coins + finalPayout).toFixed(2),
      );
      storedPottedBonsaisRef.current.splice(idx, 1);
      sanctuaryInventoryRef.current.storedBonsais = storedPottedBonsaisRef.current;

      if (isMatch && match.key) {
        eco.requestCounts[match.key] = (eco.requestCounts[match.key] || 0) + 1;
        if (isEcoRequestComplete(eco.activeRequestIndex, eco.requestCounts)) {
          const finishedNum = eco.activeRequestIndex + 1;
          eco.completedRequests = Math.min(10, eco.completedRequests + 1);
          eco.activeRequestIndex = Math.min(10, eco.activeRequestIndex + 1);
          eco.requestCounts = {};
          gameAudio.playVictoryFanfare();
          triggerNotification(
            `🎉 Eco Request #${finishedNum} Completed!${finishedNum < 10 ? ` (Advanced to Request #${finishedNum + 1})` : ' (All 10 Requests Finished - Complete Rank 1 at Bonsai Society!)'}`,
            '#facc15',
            4500,
          );
        } else {
          gameAudio.playPowerupChime();
          triggerNotification(
            `🌟 Eco Request Progress! (+${finalPayout.toFixed(2)} Verdure - 2x Bonus)`,
            '#34d399',
            3500,
          );
        }
        refreshMasterQuests();
      } else {
        gameAudio.playCoinPickup();
        triggerNotification(
          `🌱 Donated stored ${getBonsaiDisplayName(bonsai)} (Lv.${bonsai.level}) for +${finalPayout.toFixed(2)} Verdure!`,
          '#10b981',
        );
      }

      refreshHud();
    },
    [refreshHud, refreshMasterQuests, triggerNotification],
  );
  const sellStoredPottedBonsai = donateStoredPottedBonsai;

  // --- BONSAI FAVORITE TOGGLE HANDLER ---
  const toggleBonsaiFavorite = useCallback(
    (bonsaiId: string) => {
      const planted = plantedBonsaisRef.current.find((b) => b.id === bonsaiId);
      if (planted) {
        planted.isFavorite = !planted.isFavorite;
        gameAudio.playConfirmSelect();
        triggerNotification(
          planted.isFavorite
            ? `⭐ Favorited ${getBonsaiDisplayName(planted)} (Locked from donation)`
            : `Unlocked ${getBonsaiDisplayName(planted)} (Can now be donated)`,
          planted.isFavorite ? '#fbbf24' : '#94a3b8',
        );
        refreshHud();
        return;
      }
      const stored = storedPottedBonsaisRef.current.find((b) => b.id === bonsaiId);
      if (stored) {
        stored.isFavorite = !stored.isFavorite;
        gameAudio.playConfirmSelect();
        triggerNotification(
          stored.isFavorite
            ? `⭐ Favorited ${getBonsaiDisplayName(stored)} (Locked from donation)`
            : `Unlocked ${getBonsaiDisplayName(stored)} (Can now be donated)`,
          stored.isFavorite ? '#fbbf24' : '#94a3b8',
        );
        refreshHud();
        return;
      }
    },
    [refreshHud, triggerNotification],
  );

  // --- BONSAI MASTER QUEST: RANK 1 COMPLETION HANDLERS ---
  const handleCompleteDiscoveryTier1 = useCallback(() => {
    if (masterQuestsRef.current.discovery.tier1Completed) return;
    masterQuestsRef.current.discovery.tier1Completed = true;
    (masterQuestsRef.current.discovery as any).rank = 2;
    (masterQuestsRef.current.discovery as any).completedRank = 1;
    gameAudio.playVictoryFanfare();
    triggerNotification('🎉 Discovery Quest Rank 1 Completed! Unlocked new blueprints and skills.', '#10b981', 4500);
    setGameState((prev) => ({
      ...prev,
      masterQuest: masterQuestsRef.current,
      masterQuests: masterQuestsRef.current,
    }));
    refreshMasterQuests();
    refreshHud();
  }, [refreshMasterQuests, refreshHud, triggerNotification]);

  const handleCompleteCompetitionTier1 = useCallback(() => {
    gameAudio.playErrorBuzz();
    triggerNotification('Area 1 League challenges coming soon!', '#f59e0b', 3000);
  }, [triggerNotification]);

  const handleCompleteEcoTier1 = useCallback(() => {
    if (masterQuestsRef.current.eco.tier1Completed) return;
    masterQuestsRef.current.eco.tier1Completed = true;
    (masterQuestsRef.current.eco as any).rank = 2;
    (masterQuestsRef.current.eco as any).completedRank = 1;
    gameAudio.playVictoryFanfare();
    triggerNotification('🎉 Eco Quest Rank 1 Completed! Unlocked new blueprints and skills.', '#10b981', 4500);
    setGameState((prev) => ({
      ...prev,
      masterQuest: masterQuestsRef.current,
      masterQuests: masterQuestsRef.current,
    }));
    refreshMasterQuests();
    refreshHud();
  }, [refreshMasterQuests, refreshHud, triggerNotification]);

  // --- PICK UP BONSAI INTO INVENTORY ---
  const pickUpBonsaiToInventory = useCallback(
    (bonsaiId: string) => {
      const bonsaiIdx = plantedBonsaisRef.current.findIndex((b) => b.id === bonsaiId);
      if (bonsaiIdx === -1) return;

      const bonsai = plantedBonsaisRef.current[bonsaiIdx];
      const inv = sanctuaryInventoryRef.current;

      if (bonsai.automatonTier > 0) {
        const oldKey =
          bonsai.automatonTier === 1
            ? 'automatons_tier1'
            : bonsai.automatonTier === 2
            ? 'automatons_tier2'
            : 'automatons_tier3';
        inv[oldKey] += 1;
      }

      storedPottedBonsaisRef.current.push({
        id: bonsai.id,
        leafType: bonsai.leafType,
        group: bonsai.group,
        species: bonsai.species || bonsai.leafType,
        style: bonsai.style || 'MOYOGI',
        maturity: bonsai.maturity || 'sprout',
        maturityRating: bonsai.maturityRating || getBonsaiMaturityRating(bonsai),
        name: getBonsaiDisplayName(bonsai),
        rarity: bonsai.rarity,
        nature: bonsai.nature,
        level: bonsai.level,
        progressSeconds: bonsai.progressSeconds,
        color: bonsai.color,
        flowerColor: bonsai.flowerColor,
        potColor: bonsai.potColor,
        potStyle: bonsai.potStyle,
        findOdds: bonsai.findOdds,
        attributes: bonsai.attributes || { ...DEFAULT_BONSAI_ATTRIBUTES },
        cultivationPotential: bonsai.cultivationPotential || { ...DEFAULT_CULTIVATION_POTENTIAL },
        width: bonsai.width,
        height: bonsai.height,
        isFavorite: bonsai.isFavorite,
        organicBuff: bonsai.organicBuff,
        chemicalBuff: bonsai.chemicalBuff,
      });
      sanctuaryInventoryRef.current.storedBonsais = storedPottedBonsaisRef.current;

      plantedBonsaisRef.current.splice(bonsaiIdx, 1);
      invalidateSynergiesCache();
      setInspectingBonsaiId(null);
      gameAudio.playConfirmSelect();
      addFloatingText(bonsai.x, bonsai.y - 45, `+1 ${getBonsaiDisplayName(bonsai)} Stored!`, '#38bdf8');
      triggerNotification(
        `🪴 Uprooted ${getBonsaiDisplayName(bonsai)} (Lv.${bonsai.level}) to Storage! Can be replanted anywhere later with all levels intact.`,
        '#38bdf8',
      );
      refreshHud();
    },
    [addFloatingText, refreshHud, triggerNotification],
  );

  // --- ROVER UPGRADES ---
  const getRoverBatteryCost = useCallback((lvl: number) => {
    return Math.round(120 * Math.pow(1.5, lvl));
  }, []);

  const getRoverCargoCost = useCallback((lvl: number) => {
    return Math.round(150 * Math.pow(1.5, lvl));
  }, []);

  const buyRoverBatteryUpgrade = useCallback(() => {
    const inv = sanctuaryInventoryRef.current;
    const baseCost = getRoverBatteryCost(inv.rover_battery_level);
    const cost = getDiscountedCost(baseCost);

    if (inv.coins >= cost) {
      inv.coins = Number((inv.coins - cost).toFixed(2));
      inv.rover_battery_level += 1;
      gameAudio.playPowerupChime();
      triggerNotification(
        `🚙 Rover Battery Upgraded to Level ${inv.rover_battery_level}! Max Battery: ${getMaxRoverBattery()} kWh`,
        '#f59e0b',
      );
      refreshHud();
    } else {
      gameAudio.playErrorBuzz();
      triggerNotification(`Need ${cost} Verdure to upgrade Battery! Donate mature bonsais.`, '#ef4444');
    }
  }, [getDiscountedCost, getMaxRoverBattery, getRoverBatteryCost, refreshHud, triggerNotification]);

  const buyRoverCargoUpgrade = useCallback(() => {
    const inv = sanctuaryInventoryRef.current;
    const baseCost = getRoverCargoCost(inv.rover_cargo_level);
    const cost = getDiscountedCost(baseCost);

    if (inv.coins >= cost) {
      inv.coins = Number((inv.coins - cost).toFixed(2));
      inv.rover_cargo_level += 1;
      gameAudio.playPowerupChime();
      triggerNotification(
        `🚙 Rover Cargo Bed Upgraded to Level ${inv.rover_cargo_level}! Max Capacity: ${getMaxRoverCargo()} kg`,
        '#38bdf8',
      );
      refreshHud();
    } else {
      gameAudio.playErrorBuzz();
      triggerNotification(`Need ${cost} Verdure to upgrade Cargo Bed! Donate mature bonsais.`, '#ef4444');
    }
  }, [getDiscountedCost, getMaxRoverCargo, getRoverCargoCost, refreshHud, triggerNotification]);

  // --- MODULAR ROVER LOADOUT ATTACH & DETACH SYSTEM ---
  const attachRoverModule = useCallback((modType: RoverModuleType) => {
    const inv = sanctuaryInventoryRef.current;
    const attached = inv.attached_rover_modules || [];
    const maxSlots = getRoverChassisMaxSlots(inv.rover_chassis_tier || 1);

    if (attached.length >= maxSlots) {
      gameAudio.playErrorBuzz();
      triggerNotification(`Rover chassis slots full (${attached.length}/${maxSlots})! Upgrade to higher chassis tier at Workbench.`, '#ef4444');
      return;
    }

    const available = inv.rover_modules[modType] || 0;
    if (available <= 0) {
      gameAudio.playErrorBuzz();
      triggerNotification(`No unattached ${ROVER_MODULE_CONFIGS[modType].name} in storage! Craft one at Workbench.`, '#ef4444');
      return;
    }

    inv.rover_modules[modType] = available - 1;
    if (inv.roverModules) inv.roverModules[modType] = inv.rover_modules[modType];
    attached.push(modType);
    inv.attached_rover_modules = [...attached];
    inv.attachedRoverModules = inv.attached_rover_modules;

    gameAudio.playConfirmSelect();
    const cfg = ROVER_MODULE_CONFIGS[modType];
    const power = getPowerMetrics();
    if (power.totalRequired > power.totalGenerated) {
      triggerNotification(`⚠️ Attached ${cfg.name} (${cfg.bonusLabel}, ${cfg.kw} kW), but Power Deficit (${power.totalRequired}/${power.totalGenerated} kW)! Deploy generators to restore full power.`, '#f59e0b', 4500);
    } else {
      triggerNotification(`⚙️ Attached ${cfg.name} (${cfg.bonusLabel}, ${cfg.kw} kW)! Slots: ${attached.length}/${maxSlots}`, '#38bdf8');
    }
    refreshHud();
  }, [getPowerMetrics, refreshHud, triggerNotification]);

  const detachRoverModule = useCallback((slotIdx: number) => {
    const inv = sanctuaryInventoryRef.current;
    const attached = inv.attached_rover_modules || [];
    if (slotIdx < 0 || slotIdx >= attached.length) return;

    const [detached] = attached.splice(slotIdx, 1);
    inv.attached_rover_modules = [...attached];
    inv.attachedRoverModules = inv.attached_rover_modules;
    inv.rover_modules[detached] = (inv.rover_modules[detached] || 0) + 1;
    if (inv.roverModules) inv.roverModules[detached] = inv.rover_modules[detached];

    gameAudio.playCrispClick();
    const cfg = ROVER_MODULE_CONFIGS[detached];
    triggerNotification(`📦 Detached ${cfg.name}! Module returned to storage (-${cfg.kw} kW load).`, '#f59e0b');
    refreshHud();
  }, [refreshHud, triggerNotification]);

  // --- ORGANIC WASTE & LEVEL-UP DISPATCHER ---
  const handleBonsaiLevelUp = useCallback(
    (bonsai: PlantedBonsai) => {
      bonsai.level += 1;
      bonsai.lastLevelUpTime = Date.now();

      // Expand to 2x2 footprint if reaching Rating 5 (Lv. 21+ / Ancient)
      const currentRating = getBonsaiMaturityRating(bonsai);
      if (currentRating === 5 && (bonsai.width !== 2 || bonsai.height !== 2)) {
        const bField = (bonsai as any).field || (bonsai.x < SANCTUARY_LAYOUT.leftPathX ? 'left' : bonsai.x > SANCTUARY_LAYOUT.rightPathX ? 'right' : 'main');
        const bStartX = bField === 'left' ? SANCTUARY_LAYOUT.leftStartX : bField === 'right' ? SANCTUARY_LAYOUT.rightStartX : SANCTUARY_LAYOUT.mainStartX;
        const bStartY = bField === 'left' ? SANCTUARY_LAYOUT.leftStartY : bField === 'right' ? SANCTUARY_LAYOUT.rightStartY : SANCTUARY_LAYOUT.mainStartY;
        const bMaxCols = bField === 'main' ? SANCTUARY_LAYOUT.mainCols : SANCTUARY_LAYOUT.sideCols;
        const bMaxRows = bField === 'main' ? SANCTUARY_LAYOUT.mainRows : SANCTUARY_LAYOUT.sideRows;

        const curC = bonsai.col !== undefined ? bonsai.col : Math.round((bonsai.x - bStartX) / SANCTUARY_LAYOUT.cellW);
        const curR = bonsai.row !== undefined ? bonsai.row : Math.round((bonsai.y - bStartY) / SANCTUARY_LAYOUT.cellH);
        
        // Find adjacent available 2x2 plot footprint
        const candidateOffsets = [
          { dc: 0, dr: 0 },
          { dc: -1, dr: 0 },
          { dc: 0, dr: -1 },
          { dc: -1, dr: -1 },
        ];
        let chosenCandidate: { c: number; r: number } | null = null;
        for (const { dc, dr } of candidateOffsets) {
          const testC = curC + dc;
          const testR = curR + dr;
          if (testC >= 0 && testC + 1 < bMaxCols && testR >= 0 && testR + 1 < bMaxRows) {
            let valid = true;
            for (let c = testC; c <= testC + 1; c++) {
              for (let r = testR; r <= testR + 1; r++) {
                const px = bStartX + c * SANCTUARY_LAYOUT.cellW;
                const py = bStartY + r * SANCTUARY_LAYOUT.cellH;
                if (
                  !isGridPlotUnlocked(px, py) ||
                  isPlotOccupiedByPlantedBonsai(c, r, bField, bonsai.id) ||
                  isPlotOccupiedByStructure(c, r, bField)
                ) {
                  valid = false;
                  break;
                }
              }
              if (!valid) break;
            }
            if (valid) {
              chosenCandidate = { c: testC, r: testR };
              break;
            }
          }
        }

        const finalC = chosenCandidate ? chosenCandidate.c : curC;
        const finalR = chosenCandidate ? chosenCandidate.r : curR;
        bonsai.col = finalC;
        bonsai.row = finalR;
        bonsai.field = bField;
        bonsai.width = 2;
        bonsai.height = 2;
        bonsai.maturityRating = 5;
        bonsai.x = bStartX + (finalC + 0.5) * SANCTUARY_LAYOUT.cellW;
        bonsai.y = bStartY + (finalR + 0.5) * SANCTUARY_LAYOUT.cellH;
        bonsai.gridX = bonsai.x;
        bonsai.gridY = bonsai.y;
        bonsai.radius = 60;
        invalidateSynergiesCache();
        addFloatingText(bonsai.x, bonsai.y - 70, '🌟 Expanded to 2x2 Grand Bonsai!', '#f59e0b');
        triggerNotification(`🌟 ${getBonsaiDisplayName(bonsai)} achieved Maturity Rating 5 and expanded to a magnificent 2x2 footprint!`, '#f59e0b');
      }

      // Calculate Proximity Synergies
      const synergies = getCachedBonsaiSynergies(bonsai);

      // Track Zen Milestones and Statistics
      const stats = statsRef.current;
      stats.totalLevelUps += 1;
      recordBondexEntry(bonsai.leafType, bonsai.maturity, bonsai.style);
      if (bonsai.level >= 5) {
        if (!stats.grownLv5Ids) stats.grownLv5Ids = [];
        if (!stats.grownLv5Ids.includes(bonsai.id)) stats.grownLv5Ids.push(bonsai.id);
      }
      if (bonsai.level >= 10) {
        if (!stats.maxSpecimensGrownLv10.includes(bonsai.id)) {
          stats.maxSpecimensGrownLv10.push(bonsai.id);
        }
        if (!stats.grownLv10Ids) stats.grownLv10Ids = [];
        if (!stats.grownLv10Ids.includes(bonsai.id)) stats.grownLv10Ids.push(bonsai.id);

        const mTier = (bonsai.maturity || 'sprout') as string;
        if (mTier === 'sprout') {
          if (!stats.sproutLv10MilestoneIds) stats.sproutLv10MilestoneIds = [];
          if (!stats.sproutLv10MilestoneIds.includes(bonsai.id)) stats.sproutLv10MilestoneIds.push(bonsai.id);
        } else if (mTier === 'sapling') {
          if (!stats.saplingLv10MilestoneIds) stats.saplingLv10MilestoneIds = [];
          if (!stats.saplingLv10MilestoneIds.includes(bonsai.id)) stats.saplingLv10MilestoneIds.push(bonsai.id);
        } else if (mTier === 'notable') {
          if (!stats.notableLv10MilestoneIds) stats.notableLv10MilestoneIds = [];
          if (!stats.notableLv10MilestoneIds.includes(bonsai.id)) stats.notableLv10MilestoneIds.push(bonsai.id);
        } else if (mTier === 'refined') {
          if (!stats.refinedLv10MilestoneIds) stats.refinedLv10MilestoneIds = [];
          if (!stats.refinedLv10MilestoneIds.includes(bonsai.id)) stats.refinedLv10MilestoneIds.push(bonsai.id);
        } else if (mTier === 'premium') {
          if (!stats.premiumLv10MilestoneIds) stats.premiumLv10MilestoneIds = [];
          if (!stats.premiumLv10MilestoneIds.includes(bonsai.id)) stats.premiumLv10MilestoneIds.push(bonsai.id);
        }

        const lt = bonsai.leafType || 'circle';
        const st = bonsai.style || 'MOYOGI';
        if (!stats.leafTypeStylesGrown[lt]) {
          stats.leafTypeStylesGrown[lt] = [];
        }
        if (!stats.leafTypeStylesGrown[lt].includes(st)) {
          stats.leafTypeStylesGrown[lt].push(st);
        }
        stats.groupBonsaisGrown[bonsai.group] = (stats.groupBonsaisGrown[bonsai.group] || 0) + 1;
      }
      if (bonsai.level >= 25) {
        if (!stats.maxSpecimensGrownLv25.includes(bonsai.id)) {
          stats.maxSpecimensGrownLv25.push(bonsai.id);
        }
        if (!stats.grownLv25Ids) stats.grownLv25Ids = [];
        if (!stats.grownLv25Ids.includes(bonsai.id)) stats.grownLv25Ids.push(bonsai.id);
      }
      if (bonsai.level >= 50) {
        if (!stats.maxSpecimensGrownLv50.includes(bonsai.id)) {
          stats.maxSpecimensGrownLv50.push(bonsai.id);
        }
        if (!stats.grownLv50Ids) stats.grownLv50Ids = [];
        if (!stats.grownLv50Ids.includes(bonsai.id)) stats.grownLv50Ids.push(bonsai.id);
      }
      if (bonsai.level >= 10 && (bonsai.maturity || 'sprout') === 'sprout') {
        if (!stats.sproutLv10Ids) stats.sproutLv10Ids = [];
        if (!stats.sproutLv10Ids.includes(bonsai.id)) stats.sproutLv10Ids.push(bonsai.id);
      }
      if (bonsai.level >= 15 && bonsai.maturity === 'sapling') {
        if (!stats.saplingLv15Ids) stats.saplingLv15Ids = [];
        if (!stats.saplingLv15Ids.includes(bonsai.id)) stats.saplingLv15Ids.push(bonsai.id);
      }
      if (bonsai.level >= 20 && bonsai.maturity === 'notable') {
        if (!stats.notableLv20Ids) stats.notableLv20Ids = [];
        if (!stats.notableLv20Ids.includes(bonsai.id)) stats.notableLv20Ids.push(bonsai.id);
      }
      if (bonsai.level >= 25 && bonsai.maturity === 'refined') {
        if (!stats.refinedLv25Ids) stats.refinedLv25Ids = [];
        if (!stats.refinedLv25Ids.includes(bonsai.id)) stats.refinedLv25Ids.push(bonsai.id);
      }
      if (bonsai.level >= 30 && bonsai.maturity === 'premium') {
        if (!stats.premiumLv30Ids) stats.premiumLv30Ids = [];
        if (!stats.premiumLv30Ids.includes(bonsai.id)) stats.premiumLv30Ids.push(bonsai.id);
      }
      if (bonsai.level >= 100) {
        stats.firstLevel100Reached = true;
        if (!stats.grownLv100Ids) stats.grownLv100Ids = [];
        if (!stats.grownLv100Ids.includes(bonsai.id)) stats.grownLv100Ids.push(bonsai.id);
      }

      // Check and auto-award completed milestone thresholds
      checkAndAwardMilestones();

      // Advance Cultivation Potential from Pedestals in dynamic halo spots
      if (!bonsai.cultivationPotential) {
        bonsai.cultivationPotential = { foliage: 0, branches: 0, trunk: 0, roots: 0 };
      }
      const bCol = bonsai.col !== undefined ? bonsai.col : Math.round((bonsai.x - SANCTUARY_GRID.startX) / SANCTUARY_GRID.cellW);
      const bRow = bonsai.row !== undefined ? bonsai.row : Math.round((bonsai.y - SANCTUARY_GRID.startY) / SANCTUARY_GRID.cellH);
      const haloPlots = getBonsaiHaloPlots(bCol, bRow, currentRating, SANCTUARY_GRID.cols, SANCTUARY_GRID.rows);

      const adjacentPedestals = deployedStructuresRef.current.filter((d) => {
        if (!d.type.startsWith('crystal_pedestal') && d.type !== 'empty_crystal_pedestal') return false;
        const c2 = Math.round((d.x - SANCTUARY_GRID.startX) / SANCTUARY_GRID.cellW);
        const r2 = Math.round((d.y - SANCTUARY_GRID.startY) / SANCTUARY_GRID.cellH);
        return haloPlots.some((p) => p.col === c2 && p.row === r2);
      });

      let foliageBonus = 0;
      let branchesBonus = 0;
      let trunkBonus = 0;
      let rootsBonus = 0;

      adjacentPedestals.forEach((d) => {
        if (d.socketedCrystal) {
          const str = d.socketedCrystal.strength || 0.5;
          if (d.socketedCrystal.crystalType === 'foliage') foliageBonus += str;
          else if (d.socketedCrystal.crystalType === 'branches') branchesBonus += str;
          else if (d.socketedCrystal.crystalType === 'trunk') trunkBonus += str;
          else if (d.socketedCrystal.crystalType === 'roots') rootsBonus += str;
        } else if (d.type === 'crystal_pedestal_foliage') foliageBonus += 1;
        else if (d.type === 'crystal_pedestal_branches') branchesBonus += 1;
        else if (d.type === 'crystal_pedestal_trunk') trunkBonus += 1;
        else if (d.type === 'crystal_pedestal_roots') rootsBonus += 1;
      });

      const cp = bonsai.cultivationPotential;
      cp.foliage = Math.min(1000, Number(((cp.foliage || 0) + foliageBonus).toFixed(2)));
      cp.branches = Math.min(1000, Number(((cp.branches || 0) + branchesBonus).toFixed(2)));
      cp.trunk = Math.min(1000, Number(((cp.trunk || 0) + trunkBonus).toFixed(2)));
      cp.roots = Math.min(1000, Number(((cp.roots || 0) + rootsBonus).toFixed(2)));

      const totalBonus = foliageBonus + branchesBonus + trunkBonus + rootsBonus;
      if (totalBonus > 0) {
        addFloatingText(
          bonsai.x + (Math.random() - 0.5) * 20,
          bonsai.y - 105,
          `💎 +${totalBonus.toFixed(1)} Halo Potential!`,
          '#c084fc',
        );
      }

      // Seven Lucky Gods (Fortunate Blessings): +0.01 Bonsai Baseprice per Bonsai Level Up (doubled if Torii Gate active)
      if (synergies.basePriceBonusRate > 0) {
        bonsai.basePriceBonus = Number(((bonsai.basePriceBonus || 0) + synergies.basePriceBonusRate).toFixed(4));
        addFloatingText(
          bonsai.x,
          bonsai.y - 120,
          `+${synergies.basePriceBonusRate.toFixed(2)} Baseprice! (🌟 Fortunate Blessings)`,
          '#facc15',
        );
      }

      // Stone Lantern (Skilled Knowledge): +0.5% Chance for Zen Point on Bonsai Level Up (doubled if Torii Gate active)
      if (synergies.zenPointChance > 0 && Math.random() < synergies.zenPointChance) {
        inv.zen_essence += 1;
        gameAudio.playPowerupChime();
        addFloatingText(
          bonsai.x,
          bonsai.y - 135,
          `+1 🌸 Zen Point! (🌟 Skilled Knowledge)`,
          '#ec4899',
        );
        triggerNotification(`🌸 Skilled Knowledge: Stone Lantern awarded +1 Zen Point on level up!`, '#ec4899');
      }

      let organicWasteCount = 1;
      let extraWasteTriggered = false;
      if (synergies.extraWasteChance > 0 && Math.random() < synergies.extraWasteChance) {
        organicWasteCount += 1;
        extraWasteTriggered = true;
      }
      inv.organic_waste += organicWasteCount;
      inv.organicWaste = inv.organic_waste;

      // 2. Botanist EXP Reward (Activity 2: Bonsai Leveling Up: XP = 1.0 * Maturity Factor * Species Finding Odds * ((Growth Duration Seconds / 100) + 1))
      const prevLevel = Math.max(0, bonsai.level - 1);
      const expReward = calculateBonsaiLevelUpXP(prevLevel, bonsai, bonsai);
      addPlayerXP(expReward, `${getBonsaiDisplayName(bonsai)} Level Up`);

      gameAudio.playLevelUpStinger();
      addFloatingText(
        bonsai.x,
        bonsai.y - 65,
        `★ Tree Level ${bonsai.level}! (+${expReward} XP) ★`,
        '#10b981',
      );
      addFloatingText(
        bonsai.x + (Math.random() - 0.5) * 30,
        bonsai.y - 85,
        extraWasteTriggered
          ? `+${organicWasteCount} 🍂 Organic Waste (🌟 Efficient Pruning!)`
          : `+1 🍂 Organic Waste`,
        extraWasteTriggered ? '#facc15' : '#a3e635',
      );

      // Organic waste floating leaf particles
      for (let i = 0; i < 4; i++) {
        const pAngle = Math.random() * Math.PI * 2;
        const pSpeed = 30 + Math.random() * 40;
        emitParticle(
          bonsai.x,
          bonsai.y - 20,
          Math.cos(pAngle) * pSpeed,
          Math.sin(pAngle) * pSpeed - 20,
          3 + Math.random() * 2,
          '#84cc16',
          0.8,
        );
      }

      triggerNotification(`🌱 ${getBonsaiDisplayName(bonsai)} grew to Level ${bonsai.level}! (+1 🍂 Organic Waste Collected)`, '#84cc16');

      // Win Condition: Cultivate any Premium (五, Rank V) Bonsai to Level 100!
      if (bonsai.maturity === 'premium' && bonsai.level >= 100) {
        setGameState((prev) => ({
          ...prev,
          status: 'VICTORY',
          score: prev.score + 100000,
        }));
      }
    },
    [addFloatingText, gainPlayerExp, triggerNotification],
  );

  // --- PROGRESSION ADVANCE WITH LEVEL OVERFLOW ROLLOVER ---
  const advanceBonsaiProgress = useCallback(
    (bonsai: PlantedBonsai, addSeconds = 0) => {
      if (bonsai.level >= 100) {
        bonsai.progressSeconds = 0;
        return;
      }
      bonsai.progressSeconds += addSeconds;
      while (bonsai.level < 100) {
        const targetSeconds = getRequiredGrowthDuration(
          bonsai.level,
          bonsai.maturityRating || bonsai.maturity || bonsai,
        );
        if (bonsai.progressSeconds >= targetSeconds) {
          bonsai.progressSeconds -= targetSeconds;
          handleBonsaiLevelUp(bonsai);
        } else {
          break;
        }
      }
      if (bonsai.level >= 100) {
        bonsai.progressSeconds = 0;
      }
    },
    [handleBonsaiLevelUp],
  );

  // --- APPLY TIERED ORGANIC COMPOST (S, M, L BUFFS) ---
  const applyOrganicCompost = useCallback(
    (bonsaiId: string, targetTier?: 'S' | 'M' | 'L') => {
      const bonsai = plantedBonsaisRef.current.find((b) => b.id === bonsaiId);
      if (!bonsai) return;

      // SINGLE-BUFF GATING: Prevent accidental overwriting of active organic buff
      if (bonsai.organicBuff && bonsai.organicBuff.expiresAt > Date.now()) {
        gameAudio.playErrorBuzz();
        triggerNotification('Active Compost buff already running!', '#f59e0b');
        return;
      }

      const inv = sanctuaryInventoryRef.current;

      // Determine tier to use: targetTier if available, otherwise highest available (L > M > S)
      let tierToUse: 'S' | 'M' | 'L' | null = null;
      if (targetTier && (inv[`compost_${targetTier.toLowerCase()}`] || 0) > 0) {
        tierToUse = targetTier;
      } else if ((inv.compost_l || 0) > 0) {
        tierToUse = 'L';
      } else if ((inv.compost_m || 0) > 0) {
        tierToUse = 'M';
      } else if ((inv.compost_s || 0) > 0) {
        tierToUse = 'S';
      }

      if (!tierToUse) {
        gameAudio.playErrorBuzz();
        triggerNotification('No Compost (S/M/L) in stock! Craft at Compost Heap.', '#ef4444');
        return;
      }

      if (bonsai.level >= 100) {
        triggerNotification('Bonsai is already at Maximum Level 100 Mastery!', '#10b981');
        return;
      }

      const synergies = getCachedBonsaiSynergies(bonsai);

      if (synergies.isStalled) {
        gameAudio.playErrorBuzz();
        addFloatingText(bonsai.x, bonsai.y - 45, '⛔ Growth Stalled!', '#f43f5e');
        triggerNotification(
          `⛔ Cannot apply boost: Stalled by repetitive surroundings! (>4 ${synergies.stalledEntityLabel || 'identical neighbors'})`,
          '#ef4444',
        );
        return;
      }

      const invKey = `compost_${tierToUse.toLowerCase()}` as 'compost_s' | 'compost_m' | 'compost_l';
      inv[invKey] = Math.max(0, (inv[invKey] || 0) - 1);

      const def = STATION_RECIPES[invKey];
      const compostDurationMult = 1 + (zenSkillsRef.current.efficientComposts || 0) * 0.10;
      const durationSeconds = Math.round(def.effectDurationSeconds * compostDurationMult);
      bonsai.organicBuff = {
        multiplier: def.effectMultiplier,
        expiresAt: Date.now() + durationSeconds * 1000,
        tier: def.tier,
      };

      gameAudio.playPowerupChime();

      for (let i = 0; i < 6; i++) {
        const pAngle = Math.random() * Math.PI * 2;
        const pSpeed = 40 + Math.random() * 50;
        emitParticle(
          bonsai.x,
          bonsai.y - 10,
          Math.cos(pAngle) * pSpeed,
          Math.sin(pAngle) * pSpeed - 25,
          3 + Math.random() * 3,
          '#84cc16',
          0.6,
        );
      }

      const boostPct = Math.round(def.effectMultiplier * 100);
      addFloatingText(bonsai.x, bonsai.y - 45, `🍂 +${boostPct}% Growth (${def.effectDurationSeconds}s)!`, '#84cc16');
      triggerNotification(`🍂 Applied ${def.name} to ${getBonsaiDisplayName(bonsai)}! +${boostPct}% Growth Speed for ${def.effectDurationSeconds}s`, '#84cc16');

      refreshHud();
    },
    [addFloatingText, gainPlayerExp, getCachedBonsaiSynergies, refreshHud, triggerNotification],
  );

  // --- APPLY TIERED CHEMICAL FERTILIZER (S, M, L BUFFS) ---
